### 参考答案  
**1. 问题分析与反转必要性**  
两数相加的核心是模拟竖式加法，需从低位到高位逐位计算并处理进位。但题目中链表是**正序存储**（如 3→4→2 表示 243），而加法需从低位开始，因此需先反转链表。  
**为什么反转？**  
- 正序链表无法直接按加法逻辑遍历（高位在前），反转后低位在前，可同步遍历两个链表。  
- 示例：链表 `2→4→3`（正序）反转后为 `3→4→2`（逆序），对应数字 342，便于从个位开始相加。  

**2. 反转链表实现**  
**怎么做？**  
使用迭代法原地反转，避免额外空间开销。  
```python  
def reverse_list(head):  
    prev = None  
    curr = head  
    while curr:  
        next_temp = curr.next  
        curr.next = prev  # 反转指针  
        prev = curr  
        curr = next_temp  
    return prev  
```  
**关键点**：通过 `prev`、`curr`、`next_temp` 三指针逐步调整节点指向，时间复杂度 O(n)，空间 O(1)。  

**3. 两数相加逻辑**  
**怎么做？**  
反转后同步遍历两个链表，逐位相加并处理进位：  
```python  
def add_two_numbers(l1, l2):  
    l1, l2 = reverse_list(l1), reverse_list(l2)  # 先反转  
    dummy = ListNode(0)  
    curr, carry = dummy, 0  
    while l1 or l2 or carry:  
        val1 = l1.val if l1 else 0  
        val2 = l2.val if l2 else 0  
        total = val1 + val2 + carry  
        carry = total // 10  
        curr.next = ListNode(total % 10)  
        curr = curr.next  
        l1, l2 = l1.next, l2.next  
    return reverse_list(dummy.next)  # 结果需再次反转恢复正序  
```  
**关键点**：  
- 处理链表长度不一致（用 `if l1 else 0` 补零）。  
- 最后进位可能生成新节点（如 99+1=100）。  

**4. 边界处理与优化**  
**为什么需要再次反转？**  
题目要求结果以**正序链表**返回（如 243+564=807 → 7→0→8 需转回 8→0→7）。  
**优化**：若允许直接返回逆序结果，可省去最后一次反转，但需明确题目要求。  

**5. 复杂度分析**  
- **时间**：O(n + m)，n、m 为两链表长度（反转 + 相加各遍历一次）。  
- **空间**：O(1)（原地反转）或 O(max(n,m))（若需新链表存储结果）。  

**总结**：通过反转链表对齐低位，结合进位处理实现高效相加，体现对链表操作和边界条件的深度把控。'),
