### 重排链表（LeetCode Hot 100）参考答案

---

#### **1. 核心思路：分治三步法**  
**为什么分治？**  
题目要求将链表按首尾交替方式重排，直接操作原链表会导致指针混乱。通过「找中点→反转后半段→合并」分治策略，可将问题拆解为独立子任务，降低复杂度。  

**怎么做？**  
```python
def reorderList(head):
    if not head or not head.next: return  # 边界处理
    # 步骤1：找中点（快慢指针）
    slow, fast = head, head
    while fast.next and fast.next.next:
        slow = slow.next
        fast = fast.next.next
    # 步骤2：分割链表
    mid = slow.next
    slow.next = None  # 断开前半段
    # 步骤3：反转后半段
    second = reverse(mid)
    # 步骤4：合并两段
    merge(head, second)
```

---

#### **2. 关键步骤详解**  
**① 找中点（快慢指针）**  
**为什么用快慢指针？**  
单链表无法随机访问，快慢指针可在一次遍历中定位中点（时间复杂度 O(n)）。快指针每次走两步，慢指针走一步，当快指针到末尾时，慢指针恰好在中点。  

**② 反转后半段链表**  
**为什么需要反转？**  
后半段链表需逆序插入，反转后可通过头插法实现交替合并。  

```python
def reverse(head):
    prev = None
    while head:
        next_temp = head.next
        head.next = prev
        prev = head
        head = next_temp
    return prev  # 返回新头节点
```

**③ 合并两段链表**  
**为什么交替合并？**  
题目要求 L0→Ln→L1→Ln-1…，需按顺序交替连接前后两段节点。  

```python
def merge(l1, l2):
    while l1 and l2:
        temp1, temp2 = l1.next, l2.next
        l1.next = l2
        l2.next = temp1
        l1, l2 = temp1, temp2
```

---

#### **3. 流程与边界处理**  
**流程图：**  
```
Head → [1→2→3→4→5] 
       ↓ 快慢指针找中点
       ↓ 分割 → [1→2→3] + [4→5]
       ↓ 反转后半段 → [1→2→3] + [5→4]
       ↓ 交替合并 → 1→5→2→4→3
```

**边界处理：**  
- 空链表/单节点：直接返回  
- 偶数长度链表：中点为前半段末尾（如 [1→2→3→4] → 中点为 2）  

---

#### **4. 复杂度分析**  
- **时间复杂度：O(n)**  
  找中点、反转、合并各遍历一次链表。  
- **空间复杂度：O(1)**  
  仅使用常数级额外指针变量。  

---

#### **5. 易错点提醒**  
- **分割时未断开链表**：`slow.next = None` 必须执行，否则合并时会形成环。  
- **反转逻辑错误**：需保存 `next_temp` 避免断链。  
- **合并顺序混乱**：交替连接时需同步更新两段指针。  

**总结：** 本题考察链表操作的综合能力，核心在于将复杂问题拆解为独立子任务，并通过指针操作高效实现。'),
