### 参考答案

**解题思路分三步：排序预处理、回溯框架、剪枝去重**  

1. **排序预处理（为什么？）**  
   重复数字会导致全排列重复，排序后相同数字相邻，便于通过剪枝避免重复。  
   **怎么做？**  
   ```java
   Arrays.sort(nums); // 使相同元素连续，如 [1,1,2] → [1,1,2]
   ```

2. **回溯框架（为什么？）**  
   全排列本质是树形结构搜索，需维护路径和状态。  
   **怎么做？**  
   - 用 `List<Integer> path` 记录当前路径，`boolean[] visited` 标记元素是否使用。  
   - 递归终止条件：`path.size() == nums.length` 时加入结果。  
   ```java
   void backtrack(List<List<Integer>> res, int[] nums, List<Integer> path, boolean[] visited) {
       if (path.size() == nums.length) {
           res.add(new ArrayList<>(path)); // 深拷贝路径
           return;
       }
       // 遍历选择列表
       for (int i = 0; i < nums.length; i++) {
           // 剪枝逻辑（见下文）
           if (visited[i]) continue;
           path.add(nums[i]);
           visited[i] = true;
           backtrack(res, nums, path, visited); // 递归
           path.remove(path.size() - 1); // 撤销选择
           visited[i] = false;
       }
   }
   ```

3. **剪枝去重（为什么？）**  
   同一层递归中，若当前元素与前一个相同且前一个未使用，则跳过（避免重复选择相同值）。  
   **怎么做？**  
   ```java
   if (i > 0 && nums[i] == nums[i-1] && !visited[i-1]) continue;
   ```  
   **关键点**：`!visited[i-1]` 表示前一个相同元素未被使用，说明当前元素是同一层的重复选择（如 `[1,1,2]` 中第二个 `1` 在第一个 `1` 未选时跳过）。

**完整流程示例**  
输入 `nums = [1,1,2]`：  
- 排序后仍为 `[1,1,2]`。  
- 回溯时，第一个 `1` 被选后，第二个 `1` 因 `visited[0]=true` 不触发剪枝；若第一个 `1` 未被选（如回溯到根节点），第二个 `1` 因 `!visited[0]` 被跳过。  
- 最终结果：`[[1,1,2],[1,2,1],[2,1,1]]`。

**复杂度**  
- 时间：O(n! × n)，剪枝减少无效分支。  
- 空间：O(n) 递归栈 + O(n) visited 数组。  

**总结**：通过排序+剪枝，在回溯中动态规避重复，比用 `Set` 去重更高效。'),
