### 二叉树的公共祖先（LCA）参考答案  

#### 1. **问题理解**  
**为什么重要**：LCA是树结构高频考点，常用于解决路径查询、权限继承等场景。  
**怎么做**：明确目标是找到两个节点 `p` 和 `q` 的**最近公共祖先**（离根最远的共同祖先）。若 `p` 或 `q` 不存在，返回 `null`。  

---

#### 2. **核心思路：后序遍历递归**  
**为什么选后序遍历**：  
- 需从底向上判断左右子树是否包含目标节点，后序遍历天然适合“自底向上”处理。  
- 若左右子树分别包含 `p` 和 `q`，当前节点即为 LCA。  

**怎么做**：  
```java
public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    if (root == null || root == p || root == q) return root; // 终止条件
    TreeNode left = lowestCommonAncestor(root.left, p, q);   // 左子树递归
    TreeNode right = lowestCommonAncestor(root.right, p, q); // 右子树递归
    if (left != null && right != null) return root; // 当前节点为LCA
    return left != null ? left : right; // 返回非空子树结果
}
```

---

#### 3. **关键逻辑解析**  
**为什么分三种情况**：  
- **左右子树均非空**：说明 `p` 和 `q` 分别在左右子树，当前节点为 LCA。  
- **仅左子树非空**：LCA 在左子树中（`q` 可能在 `p` 的子树内）。  
- **仅右子树非空**：同理，LCA 在右子树中。  

**实际场景示例**：  
```
        3
       / \
      5   1
     / \ / \
    6  2 0  8
      / \
     7   4
```
- 若 `p=5`, `q=1` → LCA 为 `3`（左右子树各含一个目标）。  
- 若 `p=5`, `q=4` → LCA 为 `5`（`4` 在 `5` 的右子树中）。  

---

#### 4. **复杂度与边界处理**  
- **时间复杂度**：O(n)，最坏遍历所有节点。  
- **空间复杂度**：O(h)，递归栈深度（`h` 为树高）。  
- **边界处理**：若 `p` 或 `q` 不存在，返回 `null`（需提前校验或假设输入合法）。  

**总结**：通过后序遍历的“自底向上”特性，高效判断 LCA 位置，代码简洁且覆盖所有场景。'),
