### 最长回文子串解题思路

**1. 问题本质与核心挑战**  
该问题要求在字符串中找到最长的连续回文子串。核心难点在于如何高效判断回文性并避免重复计算。暴力法（枚举所有子串+判断）时间复杂度O(n³)，动态规划虽优化至O(n²)但需额外空间，而**中心扩展法**在时间与空间上更均衡，适合实际场景。

**2. 解法选择：中心扩展法**  
**为什么选它？**  
- 回文串具有对称性，每个回文串必然有一个中心点（奇数长度）或中心区间（偶数长度）。  
- 通过枚举所有可能的中心点并向外扩展，可避免重复计算，时间复杂度O(n²)，空间O(1)。  

**具体实现步骤：**  
```java
public String longestPalindrome(String s) {
    if (s == null || s.length() < 2) return s;
    int start = 0, maxLen = 1;
    for (int i = 0; i < s.length(); i++) {
        // 处理奇数长度回文（以i为中心）
        int len1 = expandAroundCenter(s, i, i);
        // 处理偶数长度回文（以i和i+1为中心）
        int len2 = expandAroundCenter(s, i, i + 1);
        int len = Math.max(len1, len2);
        if (len > maxLen) {
            maxLen = len;
            start = i - (len - 1) / 2; // 计算起始位置
        }
    }
    return s.substring(start, start + maxLen);
}

private int expandAroundCenter(String s, int left, int right) {
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        left--; right++;
    }
    return right - left - 1; // 回文长度
}
```

**3. 关键细节与边界处理**  
- **奇偶中心覆盖**：通过`expandAroundCenter(s, i, i)`和`expandAroundCenter(s, i, i+1)`分别处理奇偶长度回文。  
- **起始位置计算**：`start = i - (len - 1) / 2`确保正确截取最长子串。  
- **边界条件**：空字符串、单字符直接返回原串，避免无效计算。

**4. 复杂度与优化方向**  
- **时间复杂度**：O(n²)，最坏情况（如全相同字符）仍需遍历所有中心点。  
- **空间复杂度**：O(1)，仅用常数额外空间。  
- **进一步优化**：Manacher算法可降至O(n)，但实现复杂度高，适用于极端性能要求的场景。

**5. 实际场景验证**  
测试用例：  
- 输入 `"babad"` → 输出 `"bab"` 或 `"aba"`  
- 输入 `"cbbd"` → 输出 `"bb"`  
- 输入 `""` → 输出 `""`  

**总结**：中心扩展法通过利用回文对称性，在代码简洁性与效率间取得平衡，是面试中展示算法思维与工程能力的优选方案。'),
