### 参考答案：

**1. 回溯法核心思想**  
- **为什么用回溯**：排列问题需枚举所有可能的元素顺序，回溯通过递归尝试每个位置的选择，并在回溯时撤销选择，确保覆盖所有可能性。  
- **怎么做**：维护一个路径数组`path`和标记数组`used`，递归时依次选择未使用的元素加入`path`，递归结束后撤销选择（回溯）。  

**2. 剪枝策略（去重关键）**  
- **为什么剪枝**：有序数组中重复元素会导致重复排列（如`[1,1,2]`中两个`1`交换位置结果相同）。  
- **怎么做**：  
  - 若当前元素与前一个元素相同（`nums[i] == nums[i-1]`），且前一个元素未被使用（`!used[i-1]`），说明当前分支已生成过相同排列，直接跳过。  
  - 通过`used`数组标记已选元素，避免同一层递归中重复选择相同值。  

**3. 代码实现（Go）**  
```go
func permuteUnique(nums []int) [][]int {
    var res [][]int
    used := make([]bool, len(nums))
    path := []int{}
    
    var backtrack func()
    backtrack = func() {
        if len(path) == len(nums) {
            res = append(res, append([]int{}, path...))
            return
        }
        for i := 0; i < len(nums); i++ {
            // 剪枝条件：跳过重复元素
            if i > 0 && nums[i] == nums[i-1] && !used[i-1] {
                continue
            }
            if used[i] { continue } // 已选元素跳过
            
            used[i] = true
            path = append(path, nums[i])
            backtrack()
            path = path[:len(path)-1] // 回溯
            used[i] = false
        }
    }
    backtrack()
    return res
}
```

**4. 关键点说明**  
- **有序数组前提**：题目已保证输入有序，无需额外排序。若输入无序，需先排序以集中重复元素。  
- **剪枝逻辑**：`!used[i-1]`确保同一层递归中，重复元素仅在第一次出现时处理，避免重复分支。  
- **时间复杂度**：O(n! * n)，空间复杂度O(n)（递归栈+`used`数组）。  

**5. 实际场景**  
适用于生成唯一排列的场景（如密码组合、任务调度顺序），通过剪枝大幅减少无效计算，尤其对含重复元素的数组效率提升显著。  

（总字数：约550字）'),
