### 三数之和解题思路与实现（Go）

#### **核心思路**
1. **排序预处理**  
   - **为什么**：排序后数组有序，可快速定位目标和，同时便于跳过重复元素。  
   - **怎么做**：使用 `sort.Ints(nums)` 对数组升序排序，时间复杂度 O(n log n)。

2. **固定第一个数 + 双指针**  
   - **为什么**：固定一个数后，问题转化为两数之和，双指针可将时间复杂度从 O(n²) 降至 O(n)。  
   - **怎么做**：  
     - 遍历数组固定 `nums[i]`，若 `nums[i] > 0` 直接终止（后续数均正数，和不可能为0）。  
     - 初始化左右指针 `left = i+1`, `right = len(nums)-1`，向中间收敛。  
     - 若 `sum < 0` 则 `left++`（需更大值），`sum > 0` 则 `right--`（需更小值）。

3. **跳过重复元素**  
   - **为什么**：避免结果重复（如 `[-1,-1,2]` 和 `[-1,-1,2]` 视为同一三元组）。  
   - **怎么做**：  
     - 固定数 `i` 重复时 `continue`（`i > 0 && nums[i] == nums[i-1]`）。  
     - 找到解后，`left` 和 `right` 跳过重复值（`left++` 直到 `nums[left] != nums[left-1]`）。

---

#### **代码实现**
```go
func threeSum(nums []int) [][]int {
    sort.Ints(nums)
    res := [][]int{}
    n := len(nums)
    
    for i := 0; i < n-2; i++ {
        // 跳过重复固定数
        if i > 0 && nums[i] == nums[i-1] { continue }
        // 提前终止
        if nums[i] > 0 { break }
        
        left, right := i+1, n-1
        for left < right {
            sum := nums[i] + nums[left] + nums[right]
            if sum == 0 {
                res = append(res, []int{nums[i], nums[left], nums[right]})
                // 跳过重复元素
                for left < right && nums[left] == nums[left+1] { left++ }
                for left < right && nums[right] == nums[right-1] { right-- }
                left++
                right--
            } else if sum < 0 {
                left++
            } else {
                right--
            }
        }
    }
    return res
}
```

---

#### **关键点解析**
1. **时间复杂度**：O(n²)  
   - 排序 O(n log n) + 双指针遍历 O(n²)，整体由双指针主导。  
2. **空间复杂度**：O(1)（忽略结果存储空间）。  
3. **边界处理**：  
   - 数组长度不足3时直接返回空结果。  
   - 固定数 `nums[i] > 0` 时终止循环（后续数均正数，和不可能为0）。  

---

#### **示例流程**
```
输入: [-4, -1, -1, 0, 1, 2]
排序后: [-4, -1, -1, 0, 1, 2]
固定 i=0 (-4):
  left=1, right=5 → sum=-3 → left++
  left=2, right=5 → sum=-3 → left++
  left=3, right=5 → sum=-1 → left++
  left=4, right=5 → sum=-1 → left++ → 退出
固定 i=1 (-1):
  left=2, right=5 → sum=0 → 记录 [-1,-1,2]
  跳过重复 left=3, right=4 → sum=0 → 记录 [-1,0,1]
```

**总结**：通过排序+双指针+去重，高效解决三数之和问题，避免暴力枚举的冗余计算。'),
