### 归并排序参考答案

#### 1. **核心思想：分治法**  
**为什么**：归并排序通过分治策略将问题分解为更小的子问题，避免直接处理大规模数据，同时利用合并过程保证有序性。  
**怎么做**：  
- **分割**：将数组递归拆分为左右两半，直到子数组长度为1（天然有序）。  
- **合并**：将两个有序子数组合并为一个有序数组，通过双指针比较元素大小依次放入临时数组。  
**示例**：  
```python
def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])   # 分割左半部分
    right = merge_sort(arr[mid:])  # 分割右半部分
    return merge(left, right)      # 合并有序子数组
```

---

#### 2. **时间与空间复杂度**  
**为什么**：  
- **时间复杂度**：每次分割为两半（深度为 $ \log n $），每层合并需遍历所有元素（$ O(n) $），总复杂度为 $ O(n \log n) $。  
- **空间复杂度**：合并时需额外空间存储临时数组，最坏情况下为 $ O(n) $。  
**怎么做**：  
- 通过递归深度控制分割次数，合并时动态分配临时数组，避免频繁内存申请。  

---

#### 3. **合并过程的关键细节**  
**为什么**：合并是归并排序的核心，需保证合并后数组有序且稳定（相同元素顺序不变）。  
**怎么做**：  
- 使用双指针 `i` 和 `j` 分别遍历左右子数组，比较元素后按顺序放入临时数组。  
- 处理剩余元素：若某子数组未遍历完，直接追加到结果中。  
**代码示例**：  
```python
def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:  # 稳定排序的关键
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])  # 追加剩余元素
    result.extend(right[j:])
    return result
```

---

#### 4. **实际应用场景**  
**为什么**：归并排序的稳定性（相等元素顺序不变）和 $ O(n \log n) $ 的时间复杂度使其适合以下场景：  
- **数据库排序**：需保持原始顺序（如按时间戳排序）。  
- **外部排序**：处理超出内存的大文件（如磁盘数据分块排序）。  
**怎么做**：  
- 对大文件分块读取到内存，排序后写回磁盘，最后合并有序块。  

---

#### 5. **与其他排序算法对比**  
**为什么**：归并排序虽空间开销大，但时间复杂度稳定，适合对性能要求严格的场景。  
**怎么做**：  
- 若内存受限，可选用快速排序（平均 $ O(n \log n) $，但最坏 $ O(n^2) $）；  
- 若需原地排序，可改用堆排序（$ O(1) $ 空间）。  

**总结**：归并排序通过分治和稳定合并，实现了高效且可靠的排序，是算法设计中的经典范例。'),
