### 最长上升子序列（LIS）参考答案

**1. 问题本质与基础解法**  
**为什么需要动态规划？**  
LIS的核心是找到严格递增的子序列最大长度，且子序列不要求连续。动态规划能通过局部最优解推导全局最优。  
**怎么做？**  
- **状态定义**：`dp[i]`表示以`nums[i]`结尾的LIS长度。  
- **状态转移**：遍历`i`之前的所有`j`，若`nums[j] < nums[i]`，则`dp[i] = max(dp[i], dp[j]+1)`。  
- **代码示例**：  
  ```python
  def lengthOfLIS(nums):
      if not nums: return 0
      dp = [1]*len(nums)
      for i in range(len(nums)):
          for j in range(i):
              if nums[j] < nums[i]:
                  dp[i] = max(dp[i], dp[j]+1)
      return max(dp)
  ```
**复杂度**：时间O(n²)，空间O(n)。适用于小规模数据，但效率较低。

---

**2. 优化解法：贪心+二分查找**  
**为什么优化？**  
当数据量增大时，O(n²)可能超时。通过维护一个递增数组，可将时间复杂度降至O(n log n)。  
**怎么做？**  
- **核心思想**：维护一个数组`tails`，其中`tails[k]`表示长度为`k+1`的LIS的最小尾部元素。  
- **步骤**：  
  1. 遍历每个数，若比`tails`末尾大，则追加；否则用二分查找替换`tails`中第一个≥当前数的位置。  
  2. 最终`tails`的长度即为LIS长度。  
- **代码示例**：  
  ```python
  import bisect
  def lengthOfLIS(nums):
      tails = []
      for num in nums:
          idx = bisect.bisect_left(tails, num)
          if idx == len(tails):
              tails.append(num)
          else:
              tails[idx] = num
      return len(tails)
  ```
**关键点**：`tails`并非真实LIS，但长度正确。例如输入`[10,9,2,5,3,7,101,18]`，`tails`变化为`[2,5,7,18]`，长度为4。

---

**3. 场景与扩展**  
- **适用场景**：实时数据流处理（如股票价格趋势分析）需高效计算LIS时，优先选O(n log n)解法。  
- **边界处理**：空数组返回0，单元素数组返回1。  
- **扩展问题**：若要求非严格递增（允许相等），需调整二分查找逻辑为`bisect_right`。

**总结**：动态规划直观易实现，优化解法兼顾效率与空间，面试中需根据场景灵活选择。'),
