### 参考答案：两个有序数组合并问题  

**1. 算法选择与原理**  
- **为什么选双指针法**：两个数组已有序，直接合并可避免O(n log n)的排序开销，时间复杂度更优。  
- **怎么做**：初始化两个指针`i=0, j=0`，依次比较`arr1[i]`和`arr2[j]`，将较小值放入结果数组，并移动对应指针。  
  ```java
  int[] merge(int[] arr1, int[] arr2) {
      int[] result = new int[arr1.length + arr2.length];
      int i = 0, j = 0, k = 0;
      while (i < arr1.length && j < arr2.length) {
          result[k++] = arr1[i] <= arr2[j] ? arr1[i++] : arr2[j++];
      }
      // 追加剩余元素
      while (i < arr1.length) result[k++] = arr1[i++];
      while (j < arr2.length) result[k++] = arr2[j++];
      return result;
  }
  ```

**2. 时间复杂度分析**  
- **为什么重要**：体现对算法效率的理解，避免低效方案（如先拼接再排序）。  
- **怎么做**：双指针遍历仅需O(m+n)，每个元素访问一次，空间复杂度O(m+n)（需新数组存储结果）。  

**3. 边界情况处理**  
- **为什么需考虑**：实际场景中可能遇到空数组或长度差异极大的情况。  
- **怎么做**：  
  - 若`arr1`为空，直接返回`arr2`；反之亦然。  
  - 循环结束后，用`while`追加未遍历完的数组元素（如上述代码中的后两个`while`）。  

**4. 扩展思考**  
- **为什么提优化**：展示技术深度，例如若需原地合并（如LeetCode 88题），可调整指针方向从后往前填充。  
- **怎么做**：从两个数组末尾开始比较，避免覆盖未处理数据。  

**总结**：双指针法是此类问题的最优解，核心在于利用有序性减少比较次数，同时需注意边界条件和空间效率。'),
