### 后缀表达式（逆波兰表达式）参考答案  

**1. 定义与优势**  
后缀表达式（Reverse Polish Notation）将运算符置于操作数之后，例如 `3 4 +` 表示 `3+4`。它的核心优势是**无需括号即可明确运算顺序**，且计算效率高，特别适合用栈结构处理。  

**2. 计算步骤与栈的作用**  
计算过程分为三步：  
- **分割表达式**：将输入字符串按空格分割为 token（如 `"3 4 + 2 *"` → `["3","4","+","2","*"]`）。  
- **遍历处理**：  
  - 遇到数字：直接压入栈（如 `3` → 栈 `[3]`）。  
  - 遇到运算符：弹出栈顶两个数计算，结果压回栈（如 `+` 弹出 `4` 和 `3`，计算 `7` → 栈 `[7]`）。  
- **最终结果**：栈中剩余唯一值即为答案（如 `*` 弹出 `2` 和 `7`，结果 `14`）。  

**为什么用栈？**  
栈的**后进先出（LIFO）** 特性天然匹配操作数的顺序。例如计算 `a b -` 时，先弹出 `b` 再弹出 `a`，正确执行 `a - b`。若用队列则无法保证顺序。  

**3. 代码关键点**  
```java
public int evalRPN(String[] tokens) {
    Stack<Integer> stack = new Stack<>();
    for (String token : tokens) {
        if (isOperator(token)) {
            int b = stack.pop(), a = stack.pop(); // 注意顺序！
            stack.push(calculate(a, b, token));
        } else {
            stack.push(Integer.parseInt(token));
        }
    }
    return stack.pop();
}
```
- **操作数顺序陷阱**：减法/除法需确保 `a - b` 而非 `b - a`（如 `3 4 -` 应为 `-1`）。  
- **错误处理**：需校验栈是否足够（如运算符出现时栈元素不足）。  

**4. 复杂度与场景**  
- **时间复杂度**：O(n)，单次遍历 token。  
- **空间复杂度**：O(n)，栈最多存储 n/2 个操作数。  
- **应用场景**：  
  - 编译器将中缀表达式转为后缀优化计算；  
  - 金融系统中高效处理复杂公式（如 `100 * (1 + 0.05)^2` 转为 `100 1 0.05 + 2 ^ *`）。  

**总结**：后缀表达式通过栈结构将中缀的括号依赖转化为线性计算，是算法与工程结合的典型范例。实际开发中需注意边界条件和操作数顺序，确保鲁棒性。'),
