### 参考答案（480字）

**时间复杂度与空间复杂度是衡量算法效率的核心指标，二者共同决定算法的实际可行性。**

#### 一、时间复杂度
- **定义**：描述算法执行时间随输入规模 \(n\) 增长的变化趋势，用大O表示法（如 \(O(n)\)、\(O(\log n)\)）量化。  
- **为什么重要**：直接反映算法对计算资源的消耗速度。例如，\(O(n^2)\) 的冒泡排序在处理百万级数据时可能耗时数小时，而 \(O(n \log n)\) 的快速排序仅需秒级。  
- **怎么做**：  
  1. **忽略常数因子和低阶项**：如 \(3n + 5\) 简化为 \(O(n)\)，因渐进行为由主导项决定。  
  2. **分析关键操作次数**：例如二分查找每次将问题规模减半，循环次数为 \(\log_2 n\)，故时间复杂度为 \(O(\log n)\)。  
  ```java
  // 示例：线性搜索的时间复杂度
  int search(int[] arr, int target) {
      for (int i = 0; i < arr.length; i++) { // 最多执行 n 次
          if (arr[i] == target) return i;
      }
      return -1;
  } // 时间复杂度 O(n)
  ```

#### 二、空间复杂度
- **定义**：描述算法运行时额外占用存储空间随输入规模 \(n\) 的变化趋势，同样用大O表示法。  
- **为什么重要**：内存限制直接影响算法能否运行。例如，递归深度过深可能导致栈溢出（如斐波那契递归的空间复杂度 \(O(n)\)）。  
- **怎么做**：  
  1. **统计动态分配的变量**：如创建新数组或递归调用栈。  
  2. **排除输入本身占用的空间**：仅计算算法额外消耗的空间。  
  ```java
  // 示例：归并排序的空间复杂度
  void mergeSort(int[] arr) {
      if (arr.length <= 1) return;
      int[] left = Arrays.copyOfRange(arr, 0, arr.length/2); // 分配 O(n) 空间
      mergeSort(left); // 递归调用栈深度 O(log n)
      // 总空间复杂度 O(n) + O(log n) = O(n)
  }
  ```

#### 三、关键区别与应用场景
- **时间 vs 空间**：时间关注CPU周期，空间关注内存占用。例如，动态规划用空间换时间（如斐波那契数组缓存 \(O(n)\) 空间降低时间至 \(O(n)\)）。  
- **实际权衡**：在嵌入式系统中优先优化空间复杂度，在云计算场景下更关注时间复杂度。  

**总结**：通过大O表示法抽象化分析，我们能快速预判算法性能瓶颈，指导工程选型——这是解决海量数据处理问题的基础能力。'),
