### 力扣 402（移掉 K 位数字）参考答案

**核心思路**  
本题需通过贪心策略+单调栈实现。目标是让高位尽可能小，因此当发现当前数字比前一位小时，若剩余可删除次数 `k > 0`，则删除前一位（即弹出栈顶）。最终结果需处理前导零和空值情况。

---

#### **1. 为什么用单调栈？**  
- **为什么**：数字大小由高位决定，需保证从左到右的序列尽可能递增。若遇到更小的数字，应优先删除前面较大的数字以优化高位。  
- **怎么做**：遍历数字字符串，维护一个单调递增栈。若当前数字小于栈顶且 `k > 0`，则弹出栈顶并减少 `k`，直到栈为空或条件不满足。  

**示例**：  
输入 `"1432219"`, `k=3`  
- 栈变化：`[''1''] → [''1'',''4''] → [''1'',''3''] → [''1'',''2''] → [''1'',''2'',''2''] → [''1'',''2'',''1''] → [''1'',''2'',''1'',''9'']`  
- 删除 `4,3,2`（共3次），结果 `"1219"`。

---

#### **2. 关键步骤与代码逻辑**  
```java
public String removeKdigits(String num, int k) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : num.toCharArray()) {
        while (!stack.isEmpty() && k > 0 && stack.peek() > c) {
            stack.pop();
            k--;
        }
        stack.push(c);
    }
    // 若 k 仍有剩余，删除末尾 k 位
    while (k > 0) { stack.pop(); k--; }
    
    // 拼接结果并处理前导零
    StringBuilder res = new StringBuilder();
    for (char c : stack) res.append(c);
    while (res.length() > 1 && res.charAt(0) == ''0'') res.deleteCharAt(0);
    return res.length() == 0 ? "0" : res.toString();
}
```

---

#### **3. 边界处理**  
- **为什么**：删除后可能出现全零或空值（如输入 `"10"`, `k=1` → `"0"`）。  
- **怎么做**：  
  1. 若 `k` 未用完，继续删除末尾数字（因栈已单调递增，末尾最大）。  
  2. 结果字符串需去除前导零，若全为零则返回 `"0"`。  

**示例**：  
输入 `"10200"`, `k=1` → 删除 `1` 得 `"0200"` → 去前导零后 `"200"`。

---

#### **4. 复杂度分析**  
- **时间**：O(n)，每个数字最多入栈/出栈一次。  
- **空间**：O(n)，栈存储中间结果。  

---

**总结**：通过贪心+单调栈确保高位最小化，结合边界处理覆盖所有场景。此方法高效且易于扩展至类似问题（如构造最小数）。'),
