### 合并有序数组参考答案（Java）

**1. 核心思路：双指针逆序填充**  
- **为什么**：若从前往后合并，需频繁移动元素导致O(m+n)时间复杂度；而利用nums1的预留空间，从后往前填充可避免覆盖未处理数据，实现O(1)空间复杂度。  
- **怎么做**：  
  - 初始化三个指针：`p1 = m-1`（nums1有效末尾）、`p2 = n-1`（nums2末尾）、`p = m+n-1`（结果末尾）。  
  - 循环比较`nums1[p1]`与`nums2[p2]`，将较大值放入`nums1[p]`，指针递减。  
  - 处理剩余元素（若nums2未遍历完，需补全到nums1）。  

**2. 代码实现关键点**  
```java
public void merge(int[] nums1, int m, int[] nums2, int n) {
    int p1 = m - 1, p2 = n - 1, p = m + n - 1;
    while (p1 >= 0 && p2 >= 0) {
        nums1[p--] = (nums1[p1] > nums2[p2]) ? nums1[p1--] : nums2[p2--];
    }
    // 补充nums2剩余元素（nums1剩余无需处理）
    while (p2 >= 0) {
        nums1[p--] = nums2[p2--];
    }
}
```
- **为什么补充nums2**：若nums2元素全大于nums1，需确保剩余元素被填充。  
- **为什么不用补充nums1**：nums1剩余元素已在正确位置，无需操作。  

**3. 复杂度与边界处理**  
- **时间复杂度**：O(m+n)，每个元素仅遍历一次。  
- **空间复杂度**：O(1)，原地修改nums1。  
- **边界场景**：  
  - `m=0`或`n=0`：直接返回或复制非空数组。  
  - 数组含重复值：逻辑不变，比较时自然处理。  

**4. 实际场景优化**  
- 若nums1无预留空间，需先扩容再合并（如`System.arraycopy`）。  
- 对超大数组，可考虑分块合并减少内存压力。  

**总结**：通过逆序双指针，既保证效率又避免额外空间，是工程与算法平衡的典型解法。'),
