这个题的核心是通过信号量控制三个线程的执行顺序，保证严格输出`abcabc...`的循环，我分三步说明实现和原理：
### 1. 设计选型
为什么选信号量？信号量是带计数的同步工具，只有计数器>0时线程才能获取许可，获取后计数减1，释放后加1，天然适合顺序流转的场景。我们定义3个信号量，初始状态为`semA=1，semB=0，semC=0`，初始只有A线程能获取许可，天然保证第一个输出是a，不需要额外维护状态变量。
### 2. 核心代码实现
结构如下：
```java
// 初始化信号量
Semaphore semA = new Semaphore(1);
Semaphore semB = new Semaphore(0);
Semaphore semC = new Semaphore(0);

// 以PrintA线程为例，三个线程逻辑完全对称
class PrintA implements Runnable{
    public void run(){
        for(int i=0;i<10;i++){ // 控制输出10轮abc
            semA.acquire();
            System.out.print("a");
            semB.release();
        }
    }
}
```
PrintB的run方法改为`acquire semB`、输出b、`release semC`；PrintC同理`acquire semC`、输出c、`release semA`。
### 3. 执行流程
对应流转逻辑：
```
线程A -> 获取semA(1→0) -> 输出a -> 释放semB(0→1)
线程B -> 获取semB(1→0) -> 输出b -> 释放semC(0→1)
线程C -> 获取semC(1→0) -> 输出c -> 释放semA(0→1) -> 回到A线程
```
### 4. 优势补充
相比`synchronized+wait/notify`的方案，不需要手动维护状态变量和唤醒逻辑，代码更简洁，不容易出现漏唤醒的问题。如果要调整输出轮次，只需要改线程里的循环次数即可，扩展性很好。'),
