### LRU缓存实现思路（O(1)时间复杂度）

#### 1. **核心数据结构设计**  
- **为什么**：需要同时满足快速查找（O(1)）和动态维护访问顺序（O(1)插入/删除）。  
- **怎么做**：  
  - **哈希表**：存储 `key -> 双向链表节点` 的映射，实现O(1)查找。  
  - **双向链表**：维护访问顺序（表头为最近访问，表尾为最久未使用），节点包含 `key/value` 和 `prev/next` 指针。  
  ```java
  class Node {
      int key, value;
      Node prev, next;
      Node(int k, int v) { key = k; value = v; }
  }
  ```

#### 2. **关键操作实现**  
- **访问（get）**：  
  - **为什么**：需将访问的节点移至表头，标记为“最近使用”。  
  - **怎么做**：  
    1. 通过哈希表查找节点（O(1)）。  
    2. 若存在，将节点从原位置删除并插入表头（双向链表O(1)操作）。  
    ```java
    void moveToHead(Node node) {
        removeNode(node); // 从原位置删除
        addNode(node);    // 插入表头
    }
    ```

- **插入/更新（put）**：  
  - **为什么**：容量满时需淘汰最久未使用的节点（表尾）。  
  - **怎么做**：  
    1. 若key存在，更新值并移至表头。  
    2. 若key不存在：  
       - 创建新节点插入表头。  
       - 若超出容量，删除表尾节点并同步删除哈希表entry。  
    ```java
    void put(int key, int value) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            node.value = value;
            moveToHead(node);
        } else {
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            addNode(newNode);
            if (size > capacity) {
                Node tail = removeTail(); // 删除表尾
                map.remove(tail.key);     // 同步哈希表
            }
        }
    }
    ```

#### 3. **关键细节与陷阱**  
- **为什么**：删除链表节点时必须同步删除哈希表entry，否则会导致“脏数据”（哈希表指向无效节点）。  
- **怎么做**：在 `removeNode` 和 `removeTail` 中显式调用 `map.remove(key)`。  

#### 4. **架构示意**  
```
哈希表: {1: Node(1), 2: Node(2)}
双向链表: [Head] <-> Node(2) <-> Node(1) <-> [Tail]
```

#### 总结  
通过哈希表+双向链表的组合，LRU缓存实现了O(1)的访问和删除。核心在于**动态维护访问顺序**和**同步哈希表与链表状态**，避免内存泄漏或逻辑错误。'),
