### 参考答案：手撕算法题解题框架

#### 1. **理解题意与边界条件**
   - **为什么**：明确输入输出和边界情况是避免逻辑错误的前提。例如二分查找需确认数组是否有序、是否存在重复元素。
   - **怎么做**：  
     - 拆解问题要素（如输入数组长度、目标值范围）  
