     *示例*：若题目为“在旋转排序数组中查找目标值”，需先判断旋转点位置。

#### 2. **选择算法与数据结构**
   - **为什么**：直接影响时间/空间复杂度。例如哈希表可O(1)查找，但可能牺牲空间。
   - **怎么做**：  
     - 根据问题类型匹配算法（如动态规划解决最优子结构问题）  
     - 权衡复杂度（如双指针法替代暴力遍历）  
     *示例*：两数之和问题用哈希表存储已遍历元素，将O(n²)优化至O(n)。

#### 3. **代码实现与调试**
   - **为什么**：逻辑正确性需通过具体实现验证，细节错误（如循环条件）易导致死循环或越界。
   - **怎么做**：  
     - 分步实现核心逻辑（如先写二分查找框架再填充判断条件）  
     - 用断点调试关键变量变化  
     *代码片段*：
     ```python
     def binary_search(arr, target):
         left, right = 0, len(arr)-1
         while left <= right:  # 注意等号处理单元素情况
             mid = (left + right) // 2
             if arr[mid] == target: return mid
             elif arr[mid] < target: left = mid + 1
             else: right = mid - 1
         return -1
     ```

#### 4. **测试与优化**
   - **为什么**：覆盖测试用例可发现隐藏缺陷，优化能体现工程能力。
   - **怎么做**：  
