### 最小覆盖子串参考答案  

**1. 为什么选择滑动窗口？**  
暴力枚举所有子串的时间复杂度为 O(n³)，无法通过大厂性能要求。滑动窗口通过动态调整左右指针，将时间复杂度优化至 O(n)，核心思想是**避免重复计算**：当窗口满足条件时收缩左边界寻找更优解，否则扩展右边界。  

**2. 如何实现滑动窗口？**  
- **初始化**：用 `needMap` 存储目标字符串 `t` 的字符需求（如 `t="ABC"` → `{A:1, B:1, C:1}`），`windowMap` 记录当前窗口字符统计。  
- **扩展右指针**：遍历 `s`，将右指针字符加入 `windowMap`，若该字符满足需求（`windowMap[c] <= needMap[c]`），则 `track++`（记录已满足的字符种类数）。  
- **收缩左指针**：当 `track == needMap.size()` 时，尝试收缩左边界：  
  - 若当前窗口长度更优，更新结果；  
  - 移除左指针字符，若该字符不再满足需求（`windowMap[c] < needMap[c]`），则 `track--`。  

**3. 代码关键点**  
```java
public String minWindow(String s, String t) {
    if (s.length() < t.length()) return "";
    Map<Character, Integer> needMap = new HashMap<>();
    for (char c : t.toCharArray()) needMap.put(c, needMap.getOrDefault(c, 0) + 1);
    
    int left = 0, right = 0, track = 0, minLen = Integer.MAX_VALUE;
    String res = "";
    Map<Character, Integer> windowMap = new HashMap<>();
    
    while (right < s.length()) {
        char c = s.charAt(right);
        windowMap.put(c, windowMap.getOrDefault(c, 0) + 1);
        if (needMap.containsKey(c) && windowMap.get(c) <= needMap.get(c)) track++;
        
        while (track == needMap.size()) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                res = s.substring(left, right + 1);
            }
            char leftChar = s.charAt(left);
            windowMap.put(leftChar, windowMap.get(leftChar) - 1);
            if (needMap.containsKey(leftChar) && windowMap.get(leftChar) < needMap.get(leftChar)) track--;
            left++;
        }
        right++;
    }
    return res;
}
```

**4. 复杂度与边界处理**  
- **时间复杂度**：O(n)，每个字符最多被左右指针访问两次。  
- **空间复杂度**：O(1)，哈希表大小受字符集限制（如 ASCII 为 128）。  
- **边界场景**：若 `t` 含重复字符（如 `t="AAB"`），需确保 `needMap` 记录实际需求量；若 `s` 无解，返回空字符串。  

**总结**：滑动窗口通过双指针动态维护有效区间，结合哈希表高效判断条件，是解决子串匹配类问题的最优范式。'),
