### 参考答案（400-600字）

**核心思路**：通过**无缓冲 channel 形成环形依赖**，强制协程按顺序执行。每个协程打印后向下一个协程发送信号，确保严格顺序。

---

#### 1. **为什么用 channel？**  
Go 的 channel 是 CSP 模型的核心，天然适合协程间通信。无缓冲 channel 的**发送/接收会阻塞**，可强制协程按依赖顺序执行，避免竞态条件。相比锁（如 `sync.Mutex`），channel 更符合 Go 的并发哲学，且代码更简洁。

#### 2. **具体实现步骤**  
- **创建三个无缓冲 channel**：`ch1`（A→B）、`ch2`（B→C）、`ch3`（C→A）。  
- **协程逻辑**：  
  - 协程 A：等待 `ch3` 信号 → 打印 `1` → 向 `ch1` 发送信号。  
  - 协程 B：等待 `ch1` 信号 → 打印 `2` → 向 `ch2` 发送信号。  
  - 协程 C：等待 `ch2` 信号 → 打印 `3` → 向 `ch3` 发送信号。  
- **启动顺序**：主协程先向 `ch3` 发送初始信号，触发协程 A 执行。

#### 3. **代码示例**  
```go
package main

import (
    "fmt"
)

func main() {
    ch1, ch2, ch3 := make(chan struct{}), make(chan struct{}), make(chan struct{})

    // 协程 A: 打印 1
    go func() {
        for {
            <-ch3          // 等待 C 的信号
            fmt.Print(1)
            ch1 <- struct{}{} // 通知 B
        }
    }()

    // 协程 B: 打印 2
    go func() {
        for {
            <-ch1          // 等待 A 的信号
            fmt.Print(2)
            ch2 <- struct{}{} // 通知 C
        }
    }()

    // 协程 C: 打印 3
    go func() {
        for {
            <-ch2          // 等待 B 的信号
            fmt.Print(3)
            ch3 <- struct{}{} // 通知 A
        }
    }()

    // 启动初始信号
    ch3 <- struct{}{}
    select {} // 阻塞主协程
}
```

#### 4. **关键点解析**  
- **环形依赖**：`ch3 → A → ch1 → B → ch2 → C → ch3`，形成闭环。  
- **初始信号**：主协程向 `ch3` 发送信号，打破初始阻塞状态。  
- **无缓冲 channel**：确保每次发送必须被接收，避免顺序错乱（若用缓冲 channel，可能提前发送导致乱序）。  
- **无限循环**：每个协程通过 `for` 循环持续等待信号，实现无限打印。

#### 5. **为什么不用锁？**  
锁（如 `sync.Mutex`）需要手动管理状态变量（如 `turn`），容易出错且代码冗长。而 channel 通过**数据流控制执行顺序**，更直观且符合 Go 的“不要通过共享内存通信”原则。

---

**总结**：该方案利用 channel 的阻塞特性构建环形依赖链，以最小代码量实现严格顺序控制，是 Go 并发编程的经典实践。'),
