### 合并两个有序链表参考答案

**1. 核心思路：双指针迭代法**  
**为什么**：迭代法空间复杂度O(1)，避免递归栈溢出风险，适合处理大规模数据。  
**怎么做**：  
- 创建虚拟头节点`dummy`简化边界处理  
- 用指针`cur`维护新链表尾部，比较两个链表当前节点值  
- 将较小节点接入新链表，移动对应指针  
- 处理剩余节点直接拼接  

```java
class Solution {
    public ListNode mergeTwoLists(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        
        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) {
                cur.next = l1;
                l1 = l1.next;
            } else {
                cur.next = l2;
                l2 = l2.next;
            }
            cur = cur.next;
        }
        
        cur.next = (l1 != null) ? l1 : l2;
        return dummy.next;
    }
}
```

**2. 关键细节处理**  
**为什么**：边界条件决定代码鲁棒性  
**怎么做**：  
- 空链表判断：若输入为空直接返回另一链表  
- 剩余节点处理：循环结束后直接拼接非空链表  
- 虚拟节点作用：避免单独处理头节点插入逻辑  

**3. 复杂度分析**  
- 时间复杂度：O(m+n)，m/n为两链表长度，每个节点仅访问一次  
- 空间复杂度：O(1)，仅使用常数级额外空间  

**4. 场景延伸**  
**为什么**：展示工程思维  
**怎么做**：  
- 若需原地合并可省略dummy节点，但需额外判断头节点  
- 对于K路合并场景可改用优先队列优化  

```
l1: 1->3->5    l2: 2->4->6
     ↓            ↓
dummy->1->2->3->4->5->6
```

**总结**：该解法通过双指针线性扫描实现最优时间复杂度，虚拟头节点设计显著提升代码简洁性，在实际项目中可用于日志合并、实时数据流整合等场景。'),
