### 参考答案

**1. 死锁构造原理**  
死锁需满足四个条件：互斥、持有并等待、非抢占、循环等待。通过让两个线程交叉持有对方所需锁，可构造死锁。例如：  
```java
Object lock1 = new Object();
Object lock2 = new Object();

// 线程1
synchronized(lock1) {
    synchronized(lock2) {
        // 业务逻辑
    }
}

// 线程2
synchronized(lock2) {
    synchronized(lock1) {
        // 业务逻辑
    }
}
```
**为什么**：线程1持有lock1等待lock2，线程2持有lock2等待lock1，形成循环等待。  
**怎么做**：通过`jstack`命令可观察到线程阻塞状态，验证死锁存在。

---

**2. 主动解锁方案**  
使用`ReentrantLock`的`tryLock`方法设置超时，避免无限等待：  
```java
ReentrantLock lock1 = new ReentrantLock();
ReentrantLock lock2 = new ReentrantLock();

if (lock1.tryLock(1, TimeUnit.SECONDS)) {
    try {
        if (lock2.tryLock(1, TimeUnit.SECONDS)) {
            try {
                // 业务逻辑
            } finally {
                lock2.unlock();
            }
        }
    } finally {
        lock1.unlock();
    }
}
```
**为什么**：`tryLock`超时机制打破“持有并等待”条件，若获取锁失败则释放已持锁。  
**怎么做**：通过超时重试或降级逻辑（如记录日志、调用备用服务）处理锁竞争失败场景。

---

**3. 架构级预防**  
- **固定锁顺序**：全局约定锁获取顺序（如按对象哈希值排序），避免循环等待。  
- **超时熔断**：对关键业务设置锁等待超时，触发熔断机制。  
- **监控告警**：集成Arthas等工具实时检测死锁，自动重启异常线程。  

**为什么**：从系统设计层面消除死锁条件，比运行时解锁更可靠。  
**怎么做**：在微服务架构中，通过API网关统一校验锁顺序，或在数据库层使用`SELECT ... FOR UPDATE`的超时参数。

---

**总结**：死锁本质是资源竞争问题，需结合代码级超时机制与架构级预防策略。实际场景中，优先通过固定锁顺序和监控工具规避问题，而非依赖运行时解锁。'),
