### 参考答案：用堆排序找出前K个最大值（手写堆）

---

#### **1. 问题解析**  
**为什么用堆？**  
当数据量极大时，全量排序（如快速排序）时间复杂度为O(n log n)，而只需维护大小为K的堆，时间复杂度可降至O(n log K)。  
**怎么做？**  
选择**最小堆**：堆顶始终是当前堆中最小元素，遍历数组时，若新元素大于堆顶则替换堆顶并调整堆，最终堆中即为前K大值。

---

#### **2. 核心步骤**  
```java
// 1. 初始化最小堆（容量K）
MinHeap heap = new MinHeap(K);
for (int i = 0; i < K; i++) {
    heap.add(arr[i]); // 构建初始堆
}

// 2. 遍历剩余元素
for (int i = K; i < arr.length; i++) {
    if (arr[i] > heap.peek()) { // 新元素更大
        heap.poll(); // 移除堆顶
        heap.add(arr[i]); // 插入新元素
    }
}

// 3. 堆中元素即为前K大值（需反转顺序）
```

---

#### **3. 手写堆关键逻辑**  
```java
class MinHeap {
    private int[] heap;
    private int size;

    public MinHeap(int capacity) {
        heap = new int[capacity];
        size = 0;
    }

    // 上浮调整
    private void siftUp(int index) {
        while (index > 0) {
            int parent = (index - 1) / 2;
            if (heap[index] >= heap[parent]) break;
            swap(index, parent);
            index = parent;
        }
    }

    // 下沉调整
    private void siftDown(int index) {
        int min = index;
        int left = 2 * index + 1, right = 2 * index + 2;
        if (left < size && heap[left] < heap[min]) min = left;
        if (right < size && heap[right] < heap[min]) min = right;
        if (min != index) {
            swap(index, min);
            siftDown(min);
        }
    }
}
```

---

#### **4. 复杂度与优化**  
- **时间复杂度**：O(n log K)  
  - 建堆：O(K)  
  - 遍历剩余元素：O((n-K) log K)  
- **空间复杂度**：O(K)  
- **边界处理**：若K=0或K>数组长度，直接返回空或全量排序结果。

---

#### **5. 实际场景**  
例如：从100万用户点击量中找Top 10热门商品。  
- **优势**：无需存储全部数据，适合流式数据或内存受限场景。  
- **对比**：若用快速选择算法（QuickSelect），平均O(n)，但最坏O(n²)，且需修改原数组。

---

#### **6. 延伸思考**  
若需动态更新数据（如实时流），可结合**延迟删除堆**（Lazy Deletion）处理过期元素，保证结果实时性。

---

**总结**：通过最小堆维护K个候选值，以空间换时间，是处理大规模数据Top-K问题的经典方案。手写堆需重点掌握`上浮`和`下沉`逻辑，确保堆性质正确。'),
  ('other-269', '

针对前缀树（Trie）的实现，我会从**数据结构设计**、**核心操作逻辑**以及**工程化优化**三个维度来回答。

### 1. 数据结构设计（为什么 & 怎么做）
**为什么用 Trie：** 在搜索自动补全、拼写检查等场景下，Trie 能实现 $O(L)$ 的时间复杂度（L 为字符串长度），远快于哈希表的 $O(1)$ 但需遍历前缀的场景，且天然支持前缀检索。
**怎么做：** 定义 `TrieNode` 类。
*   **子节点映射**：使用 `Map<Character, TrieNode>` 或 `TrieNode[26]` 数组存储子节点。数组在字符集固定（如小写字母）时更快，Map 更节省空间。
*   **状态标记**：`boolean isEnd` 标记单词结束；`int count` 记录经过该节点的次数（用于统计前缀数量）。

```text
      Root
     /    \
   ''a''    ''b''
   /        \
 ''p''        ''y''
|            \
''e''          ''e''
 \            \
  ''l''         ''s''
   \           \
    ''e''        ''t''
```

### 2. 核心操作逻辑（怎么做）
*   **Insert**：从根节点出发，逐字符遍历。若子节点不存在则创建，最后将目标节点的 `isEnd` 置为 true，`count` 加 1。
*   **Search**：逐字符遍历，若中途路径断开返回 false；若遍历完成，需检查最后一个节点的 `isEnd` 是否为 true（区分“前缀”与“完整单词”）。
*   **StartsWith**：逻辑同 Search，但只需确认路径存在即可，无需检查 `isEnd`。

### 3. 工程化与优化（深度体现）
*   **空间优化**：若字符集稀疏，使用 `HashMap` 代替数组可显著减少内存占用。
*   **并发安全**：服务端高并发场景下，若需支持动态插入，可使用 `ConcurrentHashMap` 作为子节点容器，或对 `count` 使用 `AtomicInteger` 保证线程安全。
*   **变体扩展**：针对“自动补全”，可在节点中增加 `List<String>` 或 `PriorityQueue` 存储高频后缀，实现 Top-K 推荐。

**代码示例（核心片段）：**
```java
class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEnd = false;
    int count = 0;
}

public void insert(String word) {
    TrieNode node = root;
    for (char c : word.toCharArray()) {
        node = node.children.computeIfAbsent(c, k -> new TrieNode());
        node.count++; // 统计前缀出现次数
    }
    node.isEnd = true;
}
```
这样设计既保证了检索效率，又兼顾了服务端对内存和并发的要求。'),
