### 参考答案：算法题代码功能与时间复杂度分析  

#### 1. **冒泡排序**  
**功能**：通过相邻元素比较交换，将最大值逐步“冒泡”至数组末尾，实现升序排列。  
**时间复杂度**：  
- **为什么是 O(n²)**：外层循环遍历 `n` 次，内层循环每次最多比较 `n-i` 次（`i` 为当前轮次），总比较次数为 `n(n-1)/2`，简化为 O(n²)。  
- **怎么做**：  
  ```java
  for (int i = 0; i < n; i++) {
      for (int j = 0; j < n - i - 1; j++) {
          if (arr[j] > arr[j+1]) swap(arr, j, j+1);
      }
  }
  ```  
**场景**：适用于小规模数据（如教学演示），但实际开发中因效率低较少使用。  

---

#### 2. **快速排序**  
**功能**：分治法，选基准值（pivot）将数组分为左右子数组，递归排序子数组。  
**时间复杂度**：  
- **为什么平均 O(n log n)**：每次分区将数组划分为两半，递归深度为 `log n`，每层分区操作需 O(n) 时间。  
- **最坏 O(n²)**：若每次 pivot 选到极值（如已排序数组选首元素），分区极度不平衡，退化为冒泡排序。  
- **怎么做**：  
  ```java
  void quickSort(int[] arr, int low, int high) {
      if (low < high) {
          int pivot = partition(arr, low, high);
          quickSort(arr, low, pivot - 1);
          quickSort(arr, pivot + 1, high);
      }
  }
  ```  
**场景**：Java 的 `Arrays.sort()` 底层对基本类型使用双轴快排，优化了最坏情况。  

---

#### 3. **二分查找**  
**功能**：在有序数组中通过比较中间元素，逐步缩小查找范围至目标值。  
**时间复杂度**：  
- **为什么是 O(log n)**：每次比较后排除一半元素，最多需 `log₂n` 次比较（如 1000 元素仅需 10 次）。  
- **怎么做**：  
  ```java
  int binarySearch(int[] arr, int target) {
      int left = 0, right = arr.length - 1;
      while (left <= right) {
          int mid = left + (right - left) / 2;
          if (arr[mid] == target) return mid;
          if (arr[mid] < target) left = mid + 1;
          else right = mid - 1;
      }
      return -1;
  }
  ```  
**场景**：数据库索引、缓存查找等高频查询场景，依赖数据有序性。  

---

### 总结  
- **核心逻辑**：时间复杂度由算法核心操作（如比较、交换）的执行次数决定，需结合循环嵌套、递归深度或数据规模变化分析。  
- **工程实践**：选择算法时需权衡数据规模、有序性及场景需求（如快排适合通用排序，二分查找需预排序）。  
- **延伸思考**：若面试官追问优化，可补充快排的随机 pivot 策略或二分查找的边界处理细节（如避免溢出）。  

（字数：约 550 字）'),
