### LRU缓存实现参考答案

**1. 核心思路与数据结构选择**  
**为什么用HashMap+双向链表？**  
- HashMap保证O(1)时间复杂度的查找/更新，双向链表维护访问顺序（头节点为最新，尾节点为最旧）。  
- 双向链表支持O(1)删除任意节点，适合LRU的“淘汰最久未使用”需求。  

**2. 关键操作流程**  
```java
class LRUCache {
    private class Node { int key, value; Node prev, next; }
    private Map<Integer, Node> map;
    private Node head, tail;
    private int capacity;
    
    public LRUCache(int capacity) {
        this.capacity = capacity;
        map = new HashMap<>();
        head = new Node(); tail = new Node();
        head.next = tail; tail.prev = head; // 初始化哨兵节点
    }
    
    public int get(int key) {
        if (!map.containsKey(key)) return -1;
        Node node = map.get(key);
        moveToFront(node); // 访问后移至链表头部
        return node.value;
    }
    
    public void put(int key, int value) {
        if (map.containsKey(key)) {
            map.get(key).value = value;
            moveToFront(map.get(key));
        } else {
            if (map.size() == capacity) {
                removeTail(); // 淘汰尾部节点
            }
            Node newNode = new Node();
            newNode.key = key; newNode.value = value;
            map.put(key, newNode);
            addToFront(newNode);
        }
    }
}
```

**3. 细节优化说明**  
- **哨兵节点**：避免头尾节点判空逻辑，简化链表操作。  
- **线程安全**：若需并发场景，可改用`ConcurrentHashMap`+`ReentrantLock`，但会增加性能开销。  
- **实际场景**：如缓存数据库查询结果，当缓存满时自动淘汰最久未访问的条目，提升命中率。  

**4. 复杂度分析**  
- 时间复杂度：`get`和`put`均为O(1)，空间复杂度O(n)。  
- 对比`LinkedHashMap`：手动实现更灵活，但需注意边界条件（如容量为0时的异常处理）。  

通过上述设计，既满足LRU语义，又兼顾性能与可扩展性，适合高并发场景下的缓存需求。'),
