### 参考答案：找出数组中第K大的数

**1. 核心思路与解法选择**  
**为什么**：该问题需平衡时间效率与场景适配性。直接排序（如快速排序）虽简单，但时间复杂度O(n log n)在大数据量时效率不足；而基于堆或快速选择的方法可优化至O(n)或O(n log K)。  
**怎么做**：  
- **快速选择（Quickselect）**：平均O(n)时间，适合单次查询。  
  ```java
  int quickSelect(int[] nums, int k) {
      int left = 0, right = nums.length - 1;
      while (true) {
          int pivotIdx = partition(nums, left, right);
          if (pivotIdx == nums.length - k) return nums[pivotIdx]; // 第K大对应索引
          else if (pivotIdx < nums.length - k) left = pivotIdx + 1;
          else right = pivotIdx - 1;
      }
  }
  ```  
  **关键点**：通过分区（partition）缩小搜索范围，避免全量排序。  

- **最小堆（Min-Heap）**：时间O(n log K)，适合动态数据流或内存受限场景。  
  ```java
  PriorityQueue<Integer> minHeap = new PriorityQueue<>();
  for (int num : nums) {
      minHeap.offer(num);
      if (minHeap.size() > k) minHeap.poll(); // 保持堆大小为K
  }
  return minHeap.peek(); // 堆顶为第K大
  ```  
  **关键点**：维护前K大的元素，堆顶即为结果。  

**2. 场景适配与优化**  
**为什么**：不同场景需权衡性能与资源。例如，若数组需多次查询第K大，预排序更优；若数据流式输入，堆更灵活。  
**怎么做**：  
- **快速选择优化**：随机化pivot避免最坏情况O(n²)。  
- **堆优化**：使用`PriorityQueue`时，初始化为`Collections.reverseOrder()`可转为最大堆，但需调整逻辑。  

**3. 边界处理与测试**  
**为什么**：需覆盖K=1（最大值）、K=数组长度（最小值）等边界。  
**怎么做**：  
- 输入校验：`if (k < 1 || k > nums.length) throw new IllegalArgumentException();`  
- 测试用例：`[3,2,1,5,6,4]`，K=2 → 输出5；`[1,1,1]`，K=2 → 输出1。  

**总结**：优先推荐快速选择（通用场景），堆方案适合动态数据。需根据数据规模、查询频率及内存限制选择，并注重边界处理与性能测试。'),
