### 二叉树展开成链表参考答案

#### 1. **问题理解与核心目标**
- **为什么重要**：该题考察对树结构操作、递归/迭代思维及空间复杂度的理解，是算法基础能力的典型体现。
- **怎么做**：需将二叉树原地转换为右子树形式的链表，保持前序遍历顺序。例如：
```
原始树：        展开后：
    1             1
   / \             \
  2   5             2
 / \   \             \
3   4   6             3
                         \
                          4
                           \
                            5
                             \
                              6
```

#### 2. **解法选择与原理**
- **为什么选递归后序遍历**：
  - 后序遍历保证左右子树先被处理，便于将左子树插入到根节点与右子树之间。
  - 时间复杂度 O(n)，空间复杂度 O(h)（h为树高），适合面试快速实现。
- **怎么做**：
  ```java
  void flatten(TreeNode root) {
      if (root == null) return;
      flatten(root.left);   // 先处理左子树
      flatten(root.right);  // 再处理右子树
      
      TreeNode left = root.left;
      TreeNode right = root.right;
      
      // 将左子树插入到右子树位置
      root.left = null;
      root.right = left;
      
      // 找到新右子树的末尾，连接原右子树
      TreeNode curr = root;
      while (curr.right != null) curr = curr.right;
      curr.right = right;
  }
  ```

#### 3. **迭代优化方案（可选加分项）**
- **为什么提迭代**：避免递归栈开销，体现工程优化意识。
- **怎么做**：用栈模拟递归过程，或采用 Morris 遍历实现 O(1) 空间：
  ```java
  TreeNode curr = root;
  while (curr != null) {
      if (curr.left != null) {
          TreeNode pred = curr.left;
          while (pred.right != null && pred.right != curr) pred = pred.right;
          if (pred.right == null) {
              pred.right = curr.right;
              curr.right = curr.left;
              curr.left = null;
          } else {
              pred.right = null; // 断开连接
          }
      }
      curr = curr.right;
  }
  ```

#### 4. **关键细节与边界处理**
- **为什么需注意空指针**：防止访问 `null.right` 导致异常。
- **怎么做**：
  - 对每个节点操作前校验 `root.left/right` 是否为空。
  - 测试用例覆盖单节点、全左斜/右斜树等极端情况。

#### 5. **复杂度分析**
- **时间复杂度**：O(n)，每个节点访问两次（递归）或一次（迭代）。
- **空间复杂度**：递归 O(h)，迭代 O(1)。

**总结**：优先推荐递归解法快速通过基础考核，若能补充迭代优化则展现深度思考能力。'),
  ('other-277', '

### 参考答案：

**1. 核心思路**  
采用二进制位枚举法，利用每个数字的二进制位表示元素是否被选入子集。例如，对于数组 `[1,2,3]`，二进制数 `011` 对应子集 `{1,2}`。这种方法避免了递归回溯的栈开销，直接通过位运算高效生成所有子集。

**2. 实现步骤**  
- **为什么用二进制？**  
  子集总数为 `2^n`（n为数组长度），每个子集唯一对应一个 `n` 位二进制数。通过遍历 `0` 到 `2^n-1` 的整数，可穷举所有组合。  
- **怎么做？**  
  1. 预分配 `List<List<Integer>>` 数组，容量为 `2^n`。  
  2. 外层循环遍历 `i` 从 `0` 到 `(1<<n)-1`，内层循环检查 `i` 的每一位：  
     ```java
     for (int i = 0; i < (1 << n); i++) {
         List<Integer> subset = new ArrayList<>();
         for (int j = 0; j < n; j++) {
             if ((i & (1 << j)) != 0) { // 检查第j位是否为1
                 subset.add(nums[j]);
             }
         }
         result.add(subset);
     }
     ```

**3. 关键点解析**  
- **位运算效率**：`(i >> j) & 1` 可快速判断第 `j` 位是否为 `1`，避免字符串转换开销。  
- **空间优化**：预分配 `List` 数组减少动态扩容成本，适合已知子集数量的场景。  
- **时间复杂度**：`O(n * 2^n)`，每个子集需遍历 `n` 位，共 `2^n` 个子集。

**4. 实际场景应用**  
在广告推荐系统中，若需生成用户兴趣标签的所有组合（如 `[音乐, 电影, 游戏]`），此方法可快速枚举所有可能的标签组合，用于策略测试。

**5. 注意事项**  
- 当 `n > 20` 时，`2^n` 会指数级增长，需评估内存限制。  
- 若需去重（如输入含重复元素），需额外排序并使用 `Set` 过滤。

**流程示意**  
```
nums = [1,2,3]  
i=0 (000) → []  
i=1 (001) → [3]  
i=2 (010) → [2]  
i=3 (011) → [2,3]  
...  
i=7 (111) → [1,2,3]  
```  
通过位掩码直接映射子集，逻辑清晰且易于调试。'),
