### 二叉树层序遍历参考答案  

**核心思路**  
层序遍历本质是广度优先搜索（BFS），需按层级从上到下、从左到右访问节点。选择队列（FIFO）作为辅助结构，因其天然支持“先入先处理”的层级顺序。  

**实现步骤**  
1. **初始化队列**：将根节点入队（若树为空则直接返回空结果）。  
2. **逐层处理**：  
   - 记录当前队列长度（即当前层节点数），避免动态扩展导致混乱。  
   - 循环取出该层所有节点，将其值加入结果列表，并将子节点（左→右）依次入队。  
3. **终止条件**：队列为空时遍历完成。  

**代码示例（Java）**  
```java
List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new LinkedList<>();
    q.add(root);
    while (!q.isEmpty()) {
        int size = q.size(); // 固定当前层节点数
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            level.add(node.val);
            if (node.left != null) q.add(node.left);
            if (node.right != null) q.add(node.right);
        }
        res.add(level);
    }
    return res;
}
```

**关键点解析**  
- **为什么用队列？**  
  队列保证父节点先于子节点被处理，且同一层节点按入队顺序（左→右）访问，避免深度优先的递归栈开销。  
- **为何记录`size`？**  
  动态获取`q.size()`会导致后续入队的子节点被误判为当前层，通过固定`size`隔离层级。  
- **时间/空间复杂度**  
  - 时间：O(n)，每个节点访问一次。  
  - 空间：O(n)，最坏情况（完全二叉树）最后一层节点数≈n/2。  

**场景延伸**  
若需返回每层节点值之和，可在`level`循环中累加`node.val`；若树结构为N叉树，只需遍历所有子节点列表入队即可复用此框架。  

**ASCII 示意图**  
```
    1
   / \
  2   3
 / \   \
4  5    6
层序遍历结果：[1] → [2,3] → [4,5,6]
```'),
  ('other-279', '

### 10亿个数去重最优解决方案（面试参考答案）

**核心思路：分治 + 哈希分片 + Bitmap**  
面对10亿级数据去重，需解决**内存瓶颈**和**计算效率**问题。以下是分层解决方案：

---

#### **1. 为什么需要分片？**  
- **内存限制**：10亿整数（假设4字节/个）需4GB内存，单机难以承载。  
- **怎么做**：通过**哈希分片**将数据打散到多个小文件，确保每个分片可放入内存。  
  ```java
  // 哈希分片示例：将数据分配到 N 个桶
  int bucketCount = 1000; // 根据内存动态调整
  for (long num : data) {
      int bucket = (int) (Math.abs(num) % bucketCount);
      writeToFile(num, bucket); // 写入第 bucket 号文件
  }
  ```

---

#### **2. 为什么用Bitmap？**  
- **空间效率**：Bitmap用1位标记数是否存在，10亿数仅需约125MB（10^9/8/1024/1024）。  
- **怎么做**：对每个分片文件，用Bitmap标记已出现的数，遍历即完成去重。  
  ```java
  // Bitmap去重示例（单分片处理）
  BitSet bitmap = new BitSet(maxValue); // 假设分片内最大值已知
  for (long num : shardData) {
      if (!bitmap.get(num)) {
          bitmap.set(num);
          output(num); // 输出唯一值
      }
  }
  ```

---

#### **3. 关键优化点**  
- **数据倾斜处理**：若某分片过大（如哈希冲突），需动态调整桶数或引入**二级哈希**。  
- **并行计算**：分片后可用多线程/分布式框架（如Spark）并行处理，加速去重。  
- **存储优化**：若数据范围稀疏（如ID不连续），改用**布隆过滤器**预过滤，但需注意误判率。

---

#### **4. 架构流程（ASCII示意图）**  
```
原始数据 
  -> 哈希分片（1000个文件） 
    -> 每个文件：Bitmap去重 
      -> 合并结果
```

---

#### **5. 为什么这是最优解？**  
- **时间复杂度**：O(N)（分片+Bitmap遍历），远优于排序的O(N log N)。  
- **空间复杂度**：O(N/K)（K为分片数），内存占用可控。  
- **扩展性**：支持水平扩展（增加分片数或节点），适合PB级数据。

**总结**：通过哈希分片解决内存问题，Bitmap保证高效去重，结合并行计算和动态调优，可应对10亿+数据场景。实际落地时需根据数据分布调整分片策略（如按业务字段分片），避免倾斜。'),
