### 参考答案：带过期淘汰的 LRU 缓存实现

#### 1. **LRU 基础实现（为什么 + 怎么做）**
   - **为什么**：LRU 需高效支持 `get`/`put` 操作（O(1)），传统数组遍历效率低，需结合哈希表 + 双向链表。
   - **怎么做**：
     - 哈希表存 `key → Node` 映射，实现 O(1) 查找。
     - 双向链表按访问顺序排列，头部为最新，尾部为最久未用。
     ```java
     class Node {
         int key, value, expireTime; // expireTime 存储过期时间戳
         Node prev, next;
     }
     ```

#### 2. **过期淘汰机制（为什么 + 怎么做）**
   - **为什么**：普通 LRU 无法处理过期数据，需额外维护过期时间，避免无效数据占用空间。
   - **怎么做**：
     - 每个节点记录 `expireTime`（插入时设置：`System.currentTimeMillis() + TTL`）。
     - `get`/`put` 时检查是否过期：若 `currentTime > expireTime`，直接删除节点并返回 null。
     ```java
     public Integer get(int key) {
         if (!map.containsKey(key)) return null;
         Node node = map.get(key);
         if (System.currentTimeMillis() > node.expireTime) {
             removeNode(node); // 删除过期节点
             return null;
         }
         moveToFront(node); // 更新访问顺序
         return node.value;
     }
     ```

#### 3. **综合流程设计（架构 + 代码）**
   - **核心逻辑**：
     ```
     HashMap<Key, Node> → 双向链表 [Head ←→ Node1 ←→ Node2 ... → Tail]
     |-> 插入时：检查容量 → 删除过期/最旧节点 → 新建节点到头部
     |-> 访问时：检查过期 → 移动到头部
     ```
   - **关键代码片段**：
     ```java
     public void put(int key, int value, long ttl) {
         if (map.containsKey(key)) {
             Node node = map.get(key);
             node.value = value;
             node.expireTime = System.currentTimeMillis() + ttl;
             moveToFront(node);
         } else {
             if (map.size() >= capacity) {
                 removeTail(); // 删除最久未用节点
             }
             Node newNode = new Node(key, value, System.currentTimeMillis() + ttl);
             addToHead(newNode);
             map.put(key, newNode);
         }
     }
     ```

#### 4. **优化与边界处理**
   - **为什么**：避免频繁删除过期节点导致性能下降。
   - **怎么做**：
     - 延迟删除：仅在 `get`/`put` 时检查当前节点是否过期。
     - 容量不足时优先删除过期节点，再删除最旧节点。
   - **时间复杂度**：所有操作 O(1)，因哈希表 + 链表操作均无遍历。

> **总结**：通过哈希表 + 双向链表 + 时间戳三重设计，兼顾 LRU 淘汰与过期清理，适用于高并发缓存场景（如 Redis 的近似实现）。'),
  ('other-282', '

### LRU缓存实现（哈希表+双向链表）参考答案  

#### **1. 为什么选择哈希表+双向链表？**  
- **为什么**：  
  - 哈希表提供O(1)的键值查找/更新，双向链表维护访问顺序（头部为最新，尾部为最旧）。  
  - 淘汰策略需快速定位最久未使用节点（链表尾部），插入/移动节点需O(1)（双向链表支持无头指针操作）。  
- **怎么做**：  
  - 哈希表`Map<Integer, Node>`存储`key→节点`映射；双向链表节点`Node`包含`key/value/prev/next`。  
  - 用**哨兵节点**（`dummyHead`/`dummyTail`）简化边界处理，避免空指针判断。  

#### **2. 核心操作流程**  
- **初始化**：  
  ```java
  class LRUCache {
      private Map<Integer, Node> map;
      private Node dummyHead, dummyTail; // 哨兵节点
      private int capacity;
      public LRUCache(int capacity) {
          this.capacity = capacity;
          map = new HashMap<>();
          dummyHead = new Node(0, 0); 
          dummyTail = new Node(0, 0);
          dummyHead.next = dummyTail;
          dummyTail.prev = dummyHead;
      }
  }
  ```  
  **结构示意**：  
  ```
  dummyHead <-> [Node1] <-> [Node2] <-> ... <-> dummyTail
  ```  

- **`get(key)`操作**：  
  - **为什么**：访问节点需标记为“最新”，需移动到链表头部。  
  - **怎么做**：  
    ```java
    public int get(int key) {
        if (!map.containsKey(key)) return -1;
        Node node = map.get(key);
        removeNode(node); // 从原位置删除
        addToHead(node);  // 插入头部
        return node.value;
    }
    ```  

- **`put(key, value)`操作**：  
  - **为什么**：新节点需插入头部，缓存满时需淘汰尾部节点。  
  - **怎么做**：  
    ```java
    public void put(int key, int value) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            node.value = value;
            removeNode(node);
            addToHead(node);
        } else {
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            addToHead(newNode);
            if (map.size() > capacity) {
                Node tail = dummyTail.prev;
                removeNode(tail);
                map.remove(tail.key);
            }
        }
    }
    ```  

#### **3. 关键辅助方法**  
- **`addToHead(node)`**：插入头部（O(1)）  
  ```java
  private void addToHead(Node node) {
      node.next = dummyHead.next;
      dummyHead.next.prev = node;
      dummyHead.next = node;
      node.prev = dummyHead;
  }
  ```  
- **`removeNode(node)`**：删除节点（O(1)）  
  ```java
  private void removeNode(Node node) {
      node.prev.next = node.next;
      node.next.prev = node.prev;
  }
  ```  

#### **4. 时间复杂度保障**  
- 所有操作（`get/put`）仅涉及哈希表查找和链表指针修改，**严格O(1)**。  
- **实际场景**：高频访问热点数据时，链表头部集中热数据，尾部淘汰冷数据，性能优于FIFO。  

#### **5. 面试加分点**  
- **边界处理**：哨兵节点避免`head/tail`为空时的特殊判断。  
- **扩展性**：可结合`ConcurrentHashMap`支持线程安全（如Redis缓存场景）。  
- **对比其他方案**：  
  - 仅用哈希表：无法O(1)淘汰最旧数据。  
  - 仅用链表：查找O(n)，不符合要求。  

**总结**：通过哈希表加速定位、双向链表维护顺序，结合哨兵节点简化操作，实现高效LRU缓存，适用于高频读写场景（如数据库连接池、CDN缓存）。'),
