### 参考答案：支持过期时间的LRU缓存设计（时间轮+异步清理）

---

#### **1. 核心数据结构设计**  
**为什么**：LRU需要快速定位最近访问的节点，而哈希表+双向链表是经典组合。  
**怎么做**：  
- **双向链表**维护访问顺序（头为最新，尾为最旧），**哈希表**存储`key→节点`映射。  
- 节点结构包含`key`、`value`、`过期时间`、`前后指针`。  
```java
class Node {
    String key;
    Object value;
    long expireTime; // 过期时间戳
    Node prev, next;
}
```

---

#### **2. 时间轮集成过期管理**  
**为什么**：时间轮（TimingWheel）比定时轮询更高效，适合海量定时任务。  
**怎么做**：  
- 使用**HashedWheelTimer**（如Netty实现）管理过期任务。  
- 插入节点时，计算`expireTime = currentTime + TTL`，将任务注册到时间轮。  
```java
// 插入时注册过期任务
timer.newTimeout(timeout -> removeExpiredKey(node.key), delay, TimeUnit.MILLISECONDS);
```

---

#### **3. 异步清理线程**  
**为什么**：避免主线程阻塞，保证缓存操作低延迟。  
**怎么做**：  
- 启动**后台线程**定期检查时间轮的过期任务队列，执行清理。  
- 清理时从双向链表和哈希表中移除节点。  
```java
// 异步清理线程
new Thread(() -> {
    while (true) {
        try {
            Timeout timeout = timer.pendingTimeouts().poll();
            if (timeout != null) removeNode(timeout.task().key);
        } catch (InterruptedException e) { break; }
    }
}).start();
```

---

#### **4. 线程安全与性能优化**  
**为什么**：高并发场景需保证读写安全，同时减少锁竞争。  
**怎么做**：  
- 使用`ReentrantReadWriteLock`保护链表和哈希表操作。  
- 时间轮任务触发清理时，通过`removeNode`方法加锁操作。  
```java
// 删除节点（线程安全）
private void removeNode(String key) {
    lock.writeLock().lock();
    try {
        Node node = map.remove(key);
        if (node != null) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
    } finally { lock.writeLock().unlock(); }
}
```

---

#### **5. 架构流程图**  
```
Client -> Cache 
          |-> [DoublyLinkedList <-> HashMap] 
          |-> TimingWheel -> AsyncCleanerThread
```

---

#### **实际场景**  
在分布式缓存（如Redis）中，类似设计用于处理海量键的过期清理，时间轮保证低延迟，异步线程避免主线程阻塞。  

**总结**：通过时间轮高效管理过期任务，异步线程解耦清理逻辑，结合LRU核心结构，实现高性能、低延迟的缓存系统。'),
