### 参考答案

#### 1. **问题本质**  
这是典型的**最大子数组和问题**（Kadane算法）。核心目标是找到连续子数组的最大和，同时记录其起止位置。  
- **为什么**：暴力枚举所有子数组的时间复杂度为O(n²)，而Kadane算法通过动态规划思想将复杂度降至O(n)，适合处理大规模实时数据（如带宽监控场景）。  
- **怎么做**：遍历数组时维护两个变量：`currentMax`（当前子数组最大和）和`globalMax`（全局最大和），同时记录区间索引。

---

#### 2. **算法原理**  
- **为什么**：若当前子数组和变为负数，说明它对后续子数组的贡献为负，应舍弃并重新从下一个元素开始计算。  
- **怎么做**：  
  ```java
  int maxSum = Integer.MIN_VALUE, currentSum = 0;
  int start = 0, end = 0, tempStart = 0;
  for (int i = 0; i < nums.length; i++) {
      if (currentSum <= 0) {
          currentSum = nums[i];
          tempStart = i; // 重置起点
      } else {
          currentSum += nums[i];
      }
      if (currentSum > maxSum) {
          maxSum = currentSum;
          start = tempStart;
          end = i; // 更新区间
      }
  }
  ```
  **关键点**：  
  - `currentSum <= 0`时重置起点，避免负数拖累后续和。  
  - 通过`tempStart`动态追踪区间起始位置。

---

#### 3. **边界处理与场景应用**  
- **为什么**：若全为负数，需返回最大单元素（如`[-5, -2, -8]`应返回`-2`）。  
- **怎么做**：初始化`maxSum = Integer.MIN_VALUE`，确保覆盖全负数场景。  
- **实际场景**：在带宽监控系统中，快速定位带宽增长最显著的时间段（如`[3, -1, 4, -2, 5]` → 区间`[0,2]`，和为6），辅助网络资源调度。

---

#### 4. **复杂度与优化**  
- **时间复杂度**：O(n)，仅需一次遍历。  
- **空间复杂度**：O(1)，仅用常数级变量。  
- **扩展性**：若需返回所有最大和区间，可额外维护列表存储结果。

---

### 总结  
通过Kadane算法高效解决连续子数组最大和问题，兼顾性能与边界场景，适用于实时数据处理场景。'),
