### 参考答案

**问题理解**  
题目要求合并两个有序链表为一个新的有序链表，且**不额外开辟空间**。核心难点在于通过指针操作直接修改原链表结构，避免创建新节点。这考察对链表底层操作的理解及空间复杂度控制能力。

---

**解决方案思路**  
采用**双指针遍历法**，通过比较两个链表当前节点的值，按顺序拼接节点。关键点：  
1. **虚拟头节点**：用 `dummy` 节点简化头节点处理，避免特殊逻辑。  
2. **指针移动规则**：始终将较小值节点接入结果链表，并移动对应指针。  
3. **剩余节点处理**：当一个链表遍历完后，直接拼接另一个链表剩余部分。  

---

**具体实现步骤**  
```java
ListNode mergeTwoLists(ListNode l1, ListNode l2) {
    ListNode dummy = new ListNode(0); // 虚拟头节点
    ListNode cur = dummy;             // 当前指针
    
    while (l1 != null && l2 != null) {
        if (l1.val < l2.val) {
            cur.next = l1;
            l1 = l1.next;
        } else {
            cur.next = l2;
            l2 = l2.next;
        }
        cur = cur.next;
    }
    
    // 拼接剩余节点
    cur.next = (l1 != null) ? l1 : l2;
    return dummy.next;
}
```

**流程示意图**  
```
初始状态:
l1: 1 → 3 → 5
l2: 2 → 4 → 6

合并过程:
dummy → 1 → 2 → 3 → 4 → 5 → 6
```

---

**复杂度与边界处理**  
- **时间复杂度**：O(m+n)，每个节点仅遍历一次。  
- **空间复杂度**：O(1)，仅用常数级指针变量。  
- **边界条件**：  
  - 若任一链表为空，直接返回另一链表（如 `l1 == null` 时返回 `l2`）。  
  - 通过 `dummy` 节点统一处理头节点，避免空指针异常。  

---

**总结**  
该方法通过双指针动态调整链表指针，既保证了有序性，又满足零额外空间的要求。实际场景中（如数据库索引合并），此类算法能显著提升内存效率。'),
