### 参考答案  

**1. 核心思路**  
该问题本质是线程同步问题，需确保两个线程按奇偶顺序交替执行。关键在于通过共享状态和条件变量控制线程的等待与唤醒，避免竞争条件。  

**2. 解决方案**  
- **为什么用 `ReentrantLock + Condition`？**  
  `synchronized` 的 `wait/notify` 无法精确控制特定线程唤醒，而 `Condition` 可区分奇偶线程的等待队列，实现精准调度。  
- **怎么做？**  
  定义共享计数器 `count`（初始值1），两个线程分别通过 `oddCond` 和 `evenCond` 协调执行：  
  ```java
  class Printer {
      private int count = 1;
      private final Lock lock = new ReentrantLock();
      private final Condition oddCond = lock.newCondition();
      private final Condition evenCond = lock.newCondition();

      void printOdd() {
          while (count <= 100) {
              lock.lock();
              try {
                  while (count % 2 != 0 && count <= 100) { // 奇数线程执行
                      System.out.println(count++);
                      evenCond.signal(); // 唤醒偶数线程
                  }
                  oddCond.await(); // 奇数线程等待
              } catch (InterruptedException e) { e.printStackTrace(); }
              finally { lock.unlock(); }
          }
      }

      void printEven() {
          while (count <= 100) {
              lock.lock();
              try {
                  while (count % 2 == 0 && count <= 100) { // 偶数线程执行
                      System.out.println(count++);
                      oddCond.signal(); // 唤醒奇数线程
                  }
                  evenCond.await(); // 偶数线程等待
              } catch (InterruptedException e) { e.printStackTrace(); }
              finally { lock.unlock(); }
          }
      }
  }
  ```  

**3. 流程说明**  
```
Thread1 (Odd) -> [Lock] -> 检查 count%2 !=0 -> 输出 -> count++ -> Signal evenCond -> Wait oddCond  
Thread2 (Even) -> [Lock] -> 检查 count%2 ==0 -> 输出 -> count++ -> Signal oddCond -> Wait evenCond  
```  
- **初始状态**：`count=1`，奇数线程先执行，输出1后唤醒偶数线程。  
- **交替逻辑**：每次输出后通过 `signal` 唤醒对方线程，自身进入等待。  
- **终止条件**：`count > 100` 时循环退出，确保两线程安全结束。  

**4. 关键点**  
- **线程安全**：计数器 `count` 在锁内操作，避免竞态条件。  
- **伪唤醒处理**：使用 `while` 循环而非 `if` 检查条件，防止意外唤醒导致逻辑错误。  
- **扩展性**：若需支持更多线程，可动态创建 `Condition` 对象并调整调度逻辑。  

**5. 其他方案对比**  
- **`Semaphore`**：需维护两个信号量，逻辑复杂且易出错。  
- **`volatile + spinlock`**：CPU 消耗高，不推荐生产环境使用。  

**总结**：通过 `ReentrantLock + Condition` 实现精准线程调度，代码简洁且符合高并发场景的最佳实践。'),
