### 二叉树层序遍历参考答案

**1. 问题理解与核心思路**  
层序遍历要求按树的层级从上到下、每层从左到右访问节点，本质是广度优先搜索（BFS）。选择队列作为核心数据结构，因为队列的先进先出特性天然匹配“逐层处理”的需求。  

**2. 实现步骤与代码示例**  
```java
public List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    if (root == null) return result;
    
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    
    while (!queue.isEmpty()) {
        int size = queue.size(); // 当前层节点数
        List<Integer> level = new ArrayList<>();
        
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            level.add(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        result.add(level);
    }
    return result;
}
```
**关键点说明**：  
- **为什么用队列？** 队列保证按层级顺序处理节点，避免深度优先的递归栈问题。  
- **如何分层？** 通过记录每层节点数（`size`），在循环中精确控制当前层的遍历范围。  

**3. 复杂度分析**  
- **时间复杂度**：O(n)，每个节点仅入队出队一次。  
- **空间复杂度**：O(n)，最坏情况下（完全二叉树）队列需存储最后一层节点（约n/2个）。  

**4. 实际应用场景**  
- **树的结构化输出**：如将树转换为JSON格式时，需按层级组织数据。  
- **分布式任务调度**：模拟任务依赖关系时，层序遍历可确保父任务先于子任务执行。  

**5. 扩展思考**  
若需优化空间，可改用迭代+深度标记（如记录节点深度），但队列方案在代码简洁性和可读性上更优。  

**ASCII流程图**：  
```
初始队列: [1] → 处理层1 → 队列: [2,3]  
处理层2 → 队列: [4,5,6] → 最终结果: [[1],[2,3],[4,5,6]]
```  
此方案兼顾效率与工程实践，适合大规模树形数据处理场景。'),
