### LRU缓存实现方案

#### 1. **核心数据结构选择**  
**为什么**：LRU需要同时满足快速查找（O(1)）和动态维护访问顺序。  
**怎么做**：  
- 使用 **哈希表（HashMap）** 存储键值对，实现O(1)的查找和更新。  
- 使用 **双向链表** 维护访问顺序，最近使用的节点放在链表头部，最久未使用的节点在尾部。  
```java
class Node {
    int key, value;
    Node prev, next;
    Node(int k, int v) { key = k; value = v; }
}
```

#### 2. **核心操作逻辑**  
**为什么**：需动态调整链表顺序以反映访问频率。  
**怎么做**：  
- **get操作**：  
  - 若键存在，将对应节点移至链表头部，返回值。  
  - 若不存在，返回-1。  
- **put操作**：  
  - 若键存在，更新值并移至头部。  
  - 若不存在：  
    - 缓存已满时，删除链表尾部节点（最久未使用）。  
    - 插入新节点到链表头部。  
```java
private void moveToFront(Node node) {
    removeNode(node); // 从原位置移除
    addToFront(node); // 插入头部
}
```

#### 3. **时间复杂度分析**  
- **get/put操作**：O(1)。哈希表查找和链表插入/删除均为常数时间。  
- **空间复杂度**：O(capacity)，存储固定大小的缓存。

#### 4. **实际场景示例**  
假设缓存容量为2，操作序列：  
```java
put(1, 1); // 链表: 1
put(2, 2); // 链表: 2 -> 1
get(1);    // 链表: 1 -> 2（1被访问）
put(3, 3); // 链表: 3 -> 1（删除最久的2）
```

#### 5. **扩展思考**  
- **线程安全**：多线程环境下需加锁（如`synchronized`或`ReentrantLock`）。  
- **优化**：Java的`LinkedHashMap`可通过重写`removeEldestEntry`方法实现LRU，但自定义实现更灵活。

**总结**：通过哈希表+双向链表的组合，LRU缓存能在O(1)时间内完成核心操作，兼顾效率与实用性。'),
  ('other-297', '

### 力扣76题（最小覆盖子串）参考答案  

#### **1. 问题分析**  
**为什么用滑动窗口？**  
暴力枚举所有子串的时间复杂度为 O(n²)，效率低下。滑动窗口通过动态调整窗口大小，避免重复计算，将复杂度降至 O(n)。  

**怎么做？**  
使用双指针（`left` 和 `right`）维护窗口，右指针扩展窗口直到满足条件，左指针收缩窗口寻找最小解。  

---

#### **2. 算法核心步骤**  
**① 初始化窗口**  
- 用 `need` 记录目标字符串 `t` 的字符需求（如 `HashMap<Character, Integer>`）。  
- `window` 记录当前窗口内字符的统计，`valid` 记录满足条件的字符数。  

**② 扩展窗口（右指针移动）**  
- 右指针 `right` 向右移动，将字符加入 `window`，若该字符在 `need` 中且满足需求，则 `valid++`。  
- **关键判断**：当 `valid == need.size()` 时，窗口满足条件，进入收缩阶段。  

**③ 收缩窗口（左指针移动）**  
- 左指针 `left` 向右移动，移除字符并更新 `window` 和 `valid`。  
- **优化点**：若移除的字符导致 `valid < need.size()`，则停止收缩，记录当前最小窗口。  

**④ 记录最小窗口**  
- 每次满足条件时，比较当前窗口长度与历史最小值，更新结果。  

---

#### **3. 代码示例（关键逻辑）**  
```java
// 初始化 need 和 window
Map<Character, Integer> need = new HashMap<>();
for (char c : t.toCharArray()) need.put(c, need.getOrDefault(c, 0) + 1);

int left = 0, right = 0, valid = 0;
String res = "";
while (right < s.length()) {
    // 扩展窗口
    char c = s.charAt(right++);
    if (need.containsKey(c)) {
        window.put(c, window.getOrDefault(c, 0) + 1);
        if (window.get(c).equals(need.get(c))) valid++;
    }
    
    // 收缩窗口
    while (valid == need.size()) {
        if (res.isEmpty() || right - left < res.length()) 
            res = s.substring(left, right);
        char d = s.charAt(left++);
        if (need.containsKey(d)) {
            if (window.get(d).equals(need.get(d))) valid--;
            window.put(d, window.get(d) - 1);
        }
    }
}
```

---

#### **4. 复杂度分析**  
- **时间复杂度**：O(n)，左右指针各遍历一次字符串。  
- **空间复杂度**：O(k)，k 为目标字符串 `t` 的唯一字符数（`need` 和 `window` 的空间）。  

---

#### **5. 边界处理**  
- 若 `t` 为空或 `s` 无法覆盖 `t`，直接返回空字符串。  
- 使用 `window.get(c).equals(need.get(c))` 避免整数装箱问题。  

**总结**：滑动窗口通过动态调整窗口边界，高效解决“最小覆盖子串”问题，核心在于维护窗口状态并快速判断条件是否满足。'),
