### 二叉树遍历的区别与实现  

#### **1. 前序遍历（Pre-order）**  
**为什么**：  
- **应用场景**：常用于复制树结构、序列化二叉树（如保存为文件），因为先访问根节点可保证父子节点的顺序一致性。  
- **核心逻辑**：根节点优先处理，适合需要“先整体后局部”的场景。  

**怎么做**：  
- **递归实现**：  
  ```java  
  void preorder(TreeNode root) {  
      if (root == null) return;  
      System.out.println(root.val); // 访问根  
      preorder(root.left);          // 递归左子树  
      preorder(root.right);         // 递归右子树  
  }  
  ```  
- **迭代实现**：用栈模拟递归，先压右子节点再压左子节点（保证左子树优先弹出）：  
  ```java  
  Stack<TreeNode> stack = new Stack<>();  
  stack.push(root);  
  while (!stack.isEmpty()) {  
      TreeNode node = stack.pop();  
      System.out.println(node.val);  
      if (node.right != null) stack.push(node.right);  
      if (node.left != null) stack.push(node.left);  
  }  
  ```  

---

#### **2. 中序遍历（In-order）**  
**为什么**：  
- **应用场景**：二叉搜索树（BST）的中序遍历结果有序，适合排序、查找范围值。  
- **核心逻辑**：左子树→根→右子树，天然符合“从小到大”的顺序。  

**怎么做**：  
- **递归实现**：  
  ```java  
  void inorder(TreeNode root) {  
      if (root == null) return;  
      inorder(root.left);           // 递归左子树  
      System.out.println(root.val); // 访问根  
      inorder(root.right);          // 递归右子树  
  }  
  ```  
- **迭代实现**：用栈模拟递归，持续向左压栈，弹出后处理右子树：  
  ```java  
  Stack<TreeNode> stack = new Stack<>();  
  TreeNode curr = root;  
  while (curr != null || !stack.isEmpty()) {  
      while (curr != null) {  
          stack.push(curr);  
          curr = curr.left;  
      }  
      curr = stack.pop();  
      System.out.println(curr.val);  
      curr = curr.right;  
  }  
  ```  

---

#### **3. 后序遍历（Post-order）**  
**为什么**：  
- **应用场景**：删除树（先处理子节点避免内存泄漏）、计算表达式（如逆波兰表达式）。  
- **核心逻辑**：左右根，确保子节点先于父节点处理。  

**怎么做**：  
- **递归实现**：  
  ```java  
  void postorder(TreeNode root) {  
      if (root == null) return;  
      postorder(root.left);         // 递归左子树  
      postorder(root.right);        // 递归右子树  
      System.out.println(root.val); // 访问根  
  }  
  ```  
- **迭代实现**：双栈法（或单栈+标记），先压左子树再右子树，最后处理根：  
  ```java  
  Stack<TreeNode> stack1 = new Stack<>(), stack2 = new Stack<>();  
  stack1.push(root);  
  while (!stack1.isEmpty()) {  
      TreeNode node = stack1.pop();  
      stack2.push(node);  
      if (node.left != null) stack1.push(node.left);  
      if (node.right != null) stack1.push(node.right);  
  }  
  while (!stack2.isEmpty()) System.out.println(stack2.pop().val);  
  ```  

---

### **总结**  
- **时间复杂度**：三种遍历均为 O(n)，空间复杂度 O(h)（h为树高）。  
- **选择依据**：  
  - 需保持结构 → 前序；  
  - 需有序序列 → 中序；  
  - 需子节点优先处理 → 后序。  
- **迭代 vs 递归**：递归代码简洁但可能栈溢出，迭代更节省空间但逻辑复杂。'),
