### 快速排序非递归实现参考答案  

#### 1. **为什么需要非递归实现？**  
- **为什么**：递归实现依赖系统调用栈，数据规模大时易栈溢出；非递归通过显式栈模拟递归过程，更可控且适合工程场景。  
- **怎么做**：用 `Stack` 存储待排序区间 `[left, right]`，循环弹出栈顶元素并分区，将左右子区间压入栈中。  

#### 2. **核心步骤与代码示例**  
```java
public void quickSort(int[] arr) {
    if (arr == null || arr.length < 2) return;
    Stack<int[]> stack = new Stack<>();
    stack.push(new int[]{0, arr.length - 1});
    
    while (!stack.isEmpty()) {
        int[] range = stack.pop();
        int pivotIndex = partition(arr, range[0], range[1]);
        
        // 先压右区间再压左区间（保证左区间先处理）
        if (pivotIndex + 1 < range[1]) stack.push(new int[]{pivotIndex + 1, range[1]});
        if (pivotIndex - 1 > range[0]) stack.push(new int[]{range[0], pivotIndex - 1});
    }
}

private int partition(int[] arr, int left, int right) {
    int pivot = arr[right];
    int i = left - 1;
    for (int j = left; j < right; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, right);
    return i + 1;
}
```

#### 3. **关键设计解析**  
- **栈操作逻辑**：  
  ```
  初始栈: [0, n-1] → 弹出后分区 → 压入 [left, pivot-1] 和 [pivot+1, right]
  ```  
  通过栈模拟递归调用顺序，避免系统栈限制。  
- **分区优化**：选择末尾元素为基准，Lomuto分区方案简单高效；实际场景中可改用随机基准避免最坏情况。  

#### 4. **复杂度与注意事项**  
- **时间复杂度**：平均 O(n log n)，最坏 O(n²)（可通过随机化基准优化）。  
- **空间复杂度**：O(log n)（栈深度），优于递归的隐式栈开销。  
- **边界处理**：需检查区间合法性（如 `pivotIndex + 1 < right`），避免无效压栈。  

#### 5. **实际应用场景**  
在大数据量排序（如日志文件处理）时，非递归版本可显式控制内存，避免递归深度导致的崩溃风险。'),
