### 蓄水池抽样算法参考答案

#### 1. **核心思想与适用场景**  
**为什么用蓄水池？**  
当数据流规模未知或过大（如日志流、实时用户行为），无法一次性加载到内存时，需在线性时间、O(k)空间内完成随机抽样。传统方法（如先统计总数再随机选）需两次遍历，而蓄水池算法仅需一次遍历。  

**怎么做？**  
- 维护一个大小为 `k` 的蓄水池（数组）。  
- 遍历数据流，对第 `i` 个元素（`i > k`）：  
  - 以概率 `k/i` 决定是否替换蓄水池中的随机元素。  
  - 若替换，随机选蓄水池中一个位置覆盖。  

#### 2. **概率均匀性证明**  
**为什么能保证每个元素被选中的概率为 `k/n`？**  
- **数学归纳法**：  
  - 前 `k` 个元素必入池，概率为 1。  
  - 对第 `i` 个元素（`i > k`），被选中的概率为 `k/i`。  
  - 后续元素替换时，当前元素不被替换的概率为 `(i-1)/i * (i-2)/(i-1) * ... * (n-1)/n = k/n`。  
  - 最终所有元素被保留的概率均为 `k/n`。  

#### 3. **代码实现（Java）**  
```java
public class ReservoirSampling {
    public static int[] sample(int[] data, int k) {
        int[] reservoir = new int[k];
        Random random = new Random();
        
        // 初始化蓄水池
        for (int i = 0; i < k; i++) {
            reservoir[i] = data[i];
        }
        
        // 遍历剩余数据
        for (int i = k; i < data.length; i++) {
            int j = random.nextInt(i + 1); // [0, i] 随机索引
            if (j < k) {
                reservoir[j] = data[i]; // 替换
            }
        }
        return reservoir;
    }
}
```  
**关键点**：  
- `random.nextInt(i + 1)` 生成 `[0, i]` 的随机数，确保 `k/i` 概率。  
- 时间复杂度 O(n)，空间 O(k)，适合流式数据。  

#### 4. **实际应用场景**  
- **日志采样**：从海量服务器日志中随机抽取 1% 进行分析。  
- **推荐系统**：实时从用户点击流中抽样生成测试集。  

#### 5. **扩展思考**  
若需加权抽样（如热门商品优先），可将概率改为 `weight[i] / total_weight`，但需动态维护权重和。  

**总结**：蓄水池算法通过概率替换实现高效抽样，是处理流式数据的经典方案，需重点掌握概率证明和边界条件处理。'),
