### 快速排序算法步骤详解（拼多多三面常见题）  
作为Java开发岗，算法题常考察基础排序。我以**快速排序**为例（拼多多高频题），因其分治思想能体现深度。以下从核心步骤展开，结合“为什么”和“怎么做”，确保面试官看到逻辑闭环。  

1. **选择pivot（基准点）**  
   - **为什么**：pivot决定分区效率。若选首/尾元素，在已排序数组中会退化为O(n²)；选中间元素或随机值可避免最坏情况，保证平均O(n log n)。  
   - **怎么做**：取数组中点索引（如`mid = low + (high - low) / 2`），用`arr[mid]`作为pivot。代码中常优化为三数取中（比较首、中、尾），但基础实现直接用中点即可。  

2. **分区操作（Partition）**  
   - **为什么**：分区是核心，确保pivot左侧≤pivot、右侧≥pivot。这减少后续递归的比较次数，避免全量遍历。  
   - **怎么做**：用双指针法。左指针`i`从`low-1`开始，右指针`j`从`low`遍历到`high-1`；若`arr[j] ≤ pivot`，则`i++`并交换`arr[i]`和`arr[j]`。最后交换`arr[i+1]`和`arr[high]`（pivot位置）。  
     **ASCII线框图**：  
     ```
     初始数组: [3, 1, 4, 1, 5]  
     pivot=5 (high index)  
     分区过程: [3,1,4,1] | 5 → 递归处理左侧  
     ```  

3. **递归排序子数组**  
   - **为什么**：分治思想将大问题拆解为独立子问题，递归终止条件（`low >= high`）保证栈深度O(log n)。  
   - **怎么做**：对pivot左侧`[low, pi-1]`和右侧`[pi+1, high]`分别调用`quickSort`。代码中需检查`low < high`避免无效递归。  

**代码示例（Java精简版）**：  
```java
public void quickSort(int[] arr, int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high); // 获取pivot索引
        quickSort(arr, low, pi - 1);        // 递归左子数组
        quickSort(arr, pi + 1, high);       // 递归右子数组
    }
}
private int partition(int[] arr, int low, int high) {
    int pivot = arr[high]; // 选high为pivot简化实现
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr, i, j); // 交换元素
        }
    }
    swap(arr, i + 1, high);
    return i + 1;
}
```

**实际场景**：在拼多多订单系统中，用于实时排序商品列表（如按价格升序）。当处理百万级数据时，快速排序的O(n log n)比冒泡排序快10倍以上，但需注意pivot选择——若数据偏态，改用随机pivot可防超时。  
**总结**：掌握分治思想是关键，面试中强调“为什么选中间pivot”和“分区双指针细节”，能体现对性能边界的思考。'),
