### 最长无重复子串参考答案

#### 1. **问题理解与核心思路**
- **为什么**：该问题本质是寻找连续子串的最大长度，需避免重复字符。暴力解法（枚举所有子串）时间复杂度为O(n²)，效率低，需优化。
- **怎么做**：采用**滑动窗口+哈希表**，动态维护当前无重复子串的区间 `[left, right]`，通过记录字符最后出现位置快速定位重复点。

#### 2. **算法实现细节**
- **为什么**：哈希表存储字符最后出现位置可O(1)判断重复，滑动窗口避免重复遍历。
- **怎么做**：
  ```java
  int lengthOfLongestSubstring(String s) {
      Map<Character, Integer> charIndex = new HashMap<>();
      int left = 0, maxLen = 0;
      for (int right = 0; right < s.length(); right++) {
          char c = s.charAt(right);
          // 若字符已存在且在当前窗口内，更新left
          if (charIndex.containsKey(c) && charIndex.get(c) >= left) {
              left = charIndex.get(c) + 1;
          }
          charIndex.put(c, right); // 更新字符位置
          maxLen = Math.max(maxLen, right - left + 1);
      }
      return maxLen;
  }
  ```
- **关键点**：
  - `left` 移动条件：当新字符 `c` 在窗口内重复时，`left` 直接跳到重复字符的下一位。
  - 示例：输入 `"abcabcbb"`，窗口变化如下：
    ```
    [a] → [ab] → [abc] → [bca] → [cab] → [abc] → [bcb] → [cb] → [b]
    ```

#### 3. **复杂度与边界处理**
- **为什么**：需确保算法鲁棒性，覆盖空字符串、全重复字符等场景。
- **怎么做**：
  - **时间复杂度**：O(n)，每个字符最多被访问两次（`right` 和 `left` 各一次）。
  - **空间复杂度**：O(min(m, n))，m为字符集大小（如ASCII为128）。
  - **边界测试**：
    ```java
    // 空字符串
    assert lengthOfLongestSubstring("") == 0;
    // 全重复
    assert lengthOfLongestSubstring("bbbb") == 1;
    ```

#### 4. **扩展思考**
- **为什么**：面试官可能追问变体（如允许k个重复字符）。
- **怎么做**：可引入**双指针+计数数组**，维护窗口内字符频次，当重复数超过k时收缩左边界。

---

**总结**：通过滑动窗口+哈希表实现线性时间解法，重点在于动态调整窗口边界并高效记录字符位置。代码简洁且覆盖核心逻辑，适合现场手写。'),
