### 无重复最长子串（滑动窗口）参考答案

#### 1. **问题理解与暴力解法局限**  
**为什么暴力法不适用？**  
暴力枚举所有子串需 $O(n^2)$ 时间，对长字符串效率极低。例如输入 `"abcabcbb"`，需检查 28 个子串，冗余计算多。  
**怎么做？**  
采用滑动窗口动态维护无重复字符区间，避免重复遍历。

---

#### 2. **滑动窗口核心思路**  
**为什么用滑动窗口？**  
通过双指针动态调整窗口边界，确保窗口内字符唯一，同时记录最大长度。  
**怎么做？**  
- **右指针 `right`**：扩展窗口，遍历每个字符。  
- **左指针 `left`**：当遇到重复字符时，跳过至重复字符的下一个位置。  
- **哈希表**：记录字符最后出现的位置，快速定位重复点。  

---

#### 3. **具体实现步骤**  
1. **初始化**：`left=0`, `max_len=0`, 字典 `char_map` 存储字符索引。  
2. **遍历字符串**：  
   - 若 `s[right]` 在 `char_map` 中且索引 ≥ `left`，说明重复，更新 `left = char_map[s[right]] + 1`。  
   - 更新 `char_map[s[right]] = right`。  
   - 计算当前窗口长度 `right - left + 1`，更新 `max_len`。  
3. **返回结果**：`max_len`。  

---

#### 4. **代码示例（关键逻辑）**  
```python
def lengthOfLongestSubstring(s):
    char_map, left, max_len = {}, 0, 0
    for right, char in enumerate(s):
        if char in char_map and char_map[char] >= left:
            left = char_map[char] + 1  # 跳过重复字符
        char_map[char] = right
        max_len = max(max_len, right - left + 1)
    return max_len
```

---

#### 5. **复杂度与边界处理**  
- **时间复杂度**：$O(n)$，每个字符最多被访问两次（左右指针各一次）。  
- **空间复杂度**：$O(\min(n, m))$，$m$ 为字符集大小（如 ASCII 为 128）。  
- **边界条件**：空字符串直接返回 0；重复字符如 `"bb"` 时，`left` 需正确跳过到第二个 `b` 后。  

---

#### 6. **优化点**  
- **字典 vs 数组**：若字符集有限（如 ASCII），可用数组替代字典，减少哈希开销。  
- **左指针移动**：取 `max(left, char_map[char] + 1)` 避免回退，例如输入 `"abba"` 时，第二个 `b` 不会导致 `left` 回退到初始位置。  

**总结**：滑动窗口通过动态调整边界和哈希表快速定位重复，将暴力法的 $O(n^2)$ 优化至 $O(n)$，是处理子串问题的经典范式。'),
