### 参考答案（适合口头表达）

这道题的核心是**高效找到每个元素右侧第一个更大值**，暴力解法O(n²)不满足要求。我的方案是**单调栈+单次遍历**，时间复杂度O(n)，空间O(n)。具体分三步：

#### 1. **为什么用单调栈？**  
   - **原因**：需要快速定位"下一个更大元素"，而单调栈能维护一个**递减序列**，当遇到比栈顶大的元素时，即可确定栈顶元素的"下一个更大值"。  
   - **关键点**：栈中存储的是**索引而非值**，方便后续赋值结果数组。

#### 2. **如何实现？**  
   - **步骤**：  
     ```cpp
     vector<int> nextGreater(vector<int>& arr) {
         stack<int> s; // 存索引
         vector<int> res(arr.size(), -1); // 默认-1
         for (int i = 0; i < arr.size(); i++) {
             while (!s.empty() && arr[i] > arr[s.top()]) {
                 res[s.top()] = arr[i]; // 找到arr[s.top()]的下一个更大值
                 s.pop();
             }
             s.push(i); // 当前元素入栈
         }
         return res;
     }
     ```
   - **逻辑**：  
     - 遍历数组时，若当前元素`arr[i]`大于栈顶元素，则`arr[i]`是栈顶元素的"下一个更大值"，弹出栈顶并记录结果。  
     - 重复此过程直到栈空或栈顶≥`arr[i]`，再将`i`压栈。  
   - **示例**：`arr = [2,1,3]`  
     - i=0: 栈=[0] → res=[-1,-1,-1]  
     - i=1: 栈=[0,1] → res=[-1,-1,-1]  
     - i=2: 弹出1(res[1]=3), 弹出0(res[0]=3) → 栈=[2], res=[3,3,-1]

#### 3. **为什么能O(n)？**  
   - 每个元素**最多入栈/出栈一次**，总操作次数≤2n，故时间O(n)。  
   - **边界处理**：结果数组初始化为-1，无需额外判断"无更大值"的情况。

#### 实际场景应用  
此算法常用于**股票价格预测**（如计算未来某天首次涨超当前价的时间）、**温度记录分析**等需高效查询"下一个更大值"的场景。

> **总结**：通过单调栈将问题转化为"动态维护候选答案集合"，避免重复比较，是典型的**空间换时间**策略。'),
  ('other-327', '

### 链表重排优化方案（以 LeetCode 143 为例）

#### 1. **问题理解与常规解法**  
**为什么**：链表重排（如 `L0→Ln→L1→Ln-1→L2→Ln-2…`）需保证节点顺序正确且避免额外空间。常规思路是分三步：找中点、反转后半段、交替合并。  
**怎么做**：  
- **找中点**：用快慢指针定位链表中间节点（慢指针走1步，快指针走2步）。  
- **反转后半段**：从中间节点开始，原地反转后半部分链表。  
- **合并**：交替连接前半段和反转后的后半段节点。  
**示例**：  
```python
# 反转链表核心逻辑
def reverse(head):
    prev, curr = None, head
    while curr:
        next_temp = curr.next
        curr.next = prev
        prev, curr = curr, next_temp
    return prev
```

#### 2. **核心优化点**  
**为什么**：减少遍历次数和空间开销是关键。例如，快慢指针可一次遍历找到中点，原地反转避免额外存储。  
**怎么做**：  
- **快慢指针找中点**：处理奇偶长度链表时，需确保中点位置正确（如 `1->2->3->4` 中点为 `2`）。  
- **原地反转**：通过指针操作直接修改 `next` 指向，空间复杂度降至 O(1)。  
- **交替合并**：用 `dummy` 节点简化头节点处理，避免边界条件判断。  
**ASCII 流程**：  
```
原链表: 1->2->3->4->5  
中点后: 1->2 | 3->4->5  
反转后: 1->2 | 5->4->3  
合并:   1->5->2->4->3
```

#### 3. **边界处理与鲁棒性**  
**为什么**：空链表、单节点等边界情况易导致空指针异常。  
**怎么做**：  
- 提前判断 `head` 或 `head.next` 是否为空。  
- 合并时确保后半段遍历完即终止（避免循环引用）。  
**代码片段**：  
```python
if not head or not head.next: return head
# 合并逻辑
while p1 and p2:
    p1.next = p2
    p2 = p2.next
    p1 = p1.next
```

#### 4. **复杂度分析**  
**时间 O(n)**：三次遍历（找中点、反转、合并）均为线性。  
**空间 O(1)**：仅用指针变量，无额外数据结构。  
**优化效果**：相比递归解法（空间 O(n)），迭代方案更适合长链表场景。

**总结**：通过快慢指针、原地反转和交替合并，可在保证正确性的同时实现最优时空复杂度，适用于工业级高频调用场景。'),
