### 二叉树锯齿形层序遍历参考答案

#### 1. **核心思路：BFS + 动态方向控制**  
**为什么**：锯齿形遍历本质是层序遍历（BFS），但需交替调整每层顺序。BFS天然适合逐层处理，通过队列可高效管理当前层节点。  
**怎么做**：  
- 使用队列存储当前层节点，遍历完一层后切换方向（左→右 / 右→左）。  
- 用布尔变量 `leftToRight` 标记当前层方向，遍历结束后取反。  
- **关键点**：每层遍历时，根据方向决定将节点值添加到结果列表的头部或尾部。  

#### 2. **代码实现与优化**  
```java
List<List<Integer>> zigzagLevelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    boolean leftToRight = true; // 初始方向：左→右

    while (!queue.isEmpty()) {
        int size = queue.size();
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            // 根据方向插入头部或尾部
            if (leftToRight) level.add(node.val);
            else level.add(0, node.val); // 插入头部实现逆序
            // 将子节点加入队列（固定顺序：左→右）
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        res.add(level);
        leftToRight = !leftToRight; // 切换方向
    }
    return res;
}
```
**为什么高效**：  
- 避免显式反转列表（如 `Collections.reverse`），通过插入头部直接生成逆序，时间复杂度 O(1)。  
- 队列始终按左→右顺序存储子节点，简化逻辑。  

#### 3. **边界条件与测试场景**  
**为什么重要**：需覆盖空树、单节点、完全二叉树等场景。  
**怎么做**：  
- **空树**：直接返回空结果（代码首行 `if (root == null)` 处理）。  
- **单节点**：仅一层，方向不影响结果。  
- **奇偶层交替**：例如 3 层树，第 1 层左→右，第 2 层右→左，第 3 层左→右。  

#### 4. **扩展思考：空间复杂度优化**  
**为什么**：若树极深，队列可能占用大量内存。  
**怎么做**：  
- 可改用迭代+双端队列（`Deque`）动态调整插入位置，但 Java 中 `LinkedList` 已支持 O(1) 头部插入，无需额外优化。  

---

**示例流程**（以输入 `[3,9,20,null,null,15,7]` 为例）：  
```
Queue: [3] → Level 0 (左→右): [3]  
Queue: [9,20] → Level 1 (右→左): [20,9]  
Queue: [15,7] → Level 2 (左→右): [15,7]  
输出: [[3], [20,9], [15,7]]
```  
**总结**：通过 BFS 框架 + 动态方向控制，以 O(N) 时间复杂度完成锯齿形遍历，代码简洁且易扩展。'),
