### 参考答案（算法岗面试）

#### 1. **全排列（Permutations）**  
**为什么用回溯？**  
全排列需枚举所有可能的元素顺序，回溯法通过递归+状态重置能系统探索所有分支，且天然支持剪枝优化。  

**怎么做？**  
- **核心逻辑**：维护`path`（当前路径）和`visited`（访问标记），递归时遍历未访问元素，加入路径后标记已访问，回溯时撤销状态。  
- **代码示例**（Python）：  
  ```python
  def permute(nums):
      res = []
      def backtrack(path, visited):
          if len(path) == len(nums):
              res.append(path[:])
              return
          for i in range(len(nums)):
              if visited[i]: continue
              visited[i] = True
              path.append(nums[i])
              backtrack(path, visited)
              path.pop()
              visited[i] = False
      backtrack([], [False]*len(nums))
      return res
  ```  
- **关键点**：时间复杂度O(n!)，空间O(n)（递归栈）。  

---

#### 2. **全组合（Combinations）**  
**为什么需要剪枝？**  
组合问题需避免重复选择（如选[1,2]和[2,1]视为相同），通过限制起始索引可跳过无效分支。  

**怎么做？**  
- **核心逻辑**：递归时传入`start_index`，每次从`start_index`开始遍历，确保后续元素不重复。  
- **代码示例**（选k个元素的组合）：  
  ```python
  def combine(n, k):
      res = []
      def backtrack(start, path):
          if len(path) == k:
              res.append(path[:])
              return
          for i in range(start, n+1):
              path.append(i)
              backtrack(i+1, path)  # 下一层从i+1开始
              path.pop()
      backtrack(1, [])
      return res
  ```  
- **关键点**：剪枝后时间复杂度O(C(n,k))，避免无效递归。  

---

#### 3. **K个有序数组排序**  
**为什么用最小堆？**  
多路归并需高效获取当前最小值，堆结构可在O(log k)时间内完成插入和弹出，优于线性扫描（O(k)）。  

**怎么做？**  
- **核心逻辑**：  
  1. 初始化最小堆，存入每个数组的首元素及来源数组索引。  
  2. 每次弹出堆顶（最小值），将对应数组的下一个元素压入堆。  
- **流程示意**：  
  ```
  Input: [[1,4], [2,5], [3,6]]
  Heap: [1(0,0), 2(1,0), 3(2,0)] → pop 1 → push 4 → Heap: [2,3,4]
  Output: [1,2,3,4,5,6]
  ```  
- **代码示例**（Python）：  
  ```python
  import heapq
  def mergeKArrays(arrays):
      heap = []
      for i, arr in enumerate(arrays):
          if arr: heapq.heappush(heap, (arr[0], i, 0))
      res = []
      while heap:
          val, arr_idx, elem_idx = heapq.heappop(heap)
          res.append(val)
          if elem_idx + 1 < len(arrays[arr_idx]):
              next_val = arrays[arr_idx][elem_idx+1]
              heapq.heappush(heap, (next_val, arr_idx, elem_idx+1))
      return res
  ```  
- **关键点**：时间复杂度O(n log k)，空间O(k)（堆大小）。  

---

**总结**：回溯法解决排列组合需注重状态管理与剪枝，多路归并依赖堆优化效率。实际场景中，全排列可用于密码破解，组合问题用于特征选择，K数组排序常见于日志合并。'),
