### 参考答案

**1. 解析策略：基于栈的层次化构建**  
- **为什么**：嵌套结构天然具有递归特性，但直接递归可能因深层嵌套导致栈溢出。使用显式栈可高效管理嵌套层级，且避免递归调用开销。  
- **怎么做**：  
  - 初始化栈，遍历字符串。  
  - 遇到 `[` 时，创建新 `NestedInteger` 列表压入栈，并添加到当前栈顶元素的子列表中。  
  - 遇到 `]` 时，弹出栈顶列表（表示当前层级结束），若栈非空则将其加入新栈顶的子列表。  
  ```java
  // 核心逻辑片段
  if (c == ''['') {
      NestedInteger ni = new NestedInteger();
      stack.peek().add(ni); // 添加到当前层级
      stack.push(ni);       // 进入新层级
  } else if (c == '']'') {
      stack.pop();          // 结束当前层级
  }
  ```

**2. 数字解析：连续字符聚合与符号处理**  
- **为什么**：字符串中的数字可能包含负号（如 `-123`），需完整截取连续数字段。  
- **怎么做**：  
  - 遇到数字或 `-` 时，向后扫描直到非数字字符，拼接为完整数值。  
  - 用 `Integer.parseInt` 转换后，直接添加到当前栈顶列表。  
  ```java
  if (Character.isDigit(c) || c == ''-'') {
      int j = i;
      while (j < s.length() && (Character.isDigit(s.charAt(j)) || s.charAt(j) == ''-'')) j++;
      int num = Integer.parseInt(s.substring(i, j));
      stack.peek().add(new NestedInteger(num));
      i = j; // 跳过已处理字符
  }
  ```

**3. 边界处理：单数字与空列表兼容**  
- **为什么**：输入可能为纯数字（如 `"123"`）或空列表（`"[]"`），需区分处理。  
- **怎么做**：  
  - 若首字符非 `[`，直接返回单数字 `NestedInteger`。  
  - 空列表通过栈最终弹出后自然处理（栈顶即为结果）。  
  ```java
  if (s.charAt(0) != ''['') return new NestedInteger(Integer.parseInt(s));
  ```

**4. 复杂度与鲁棒性**  
- **时间复杂度**：O(n)，每个字符仅遍历一次。  
- **空间复杂度**：O(n)，栈深度最大为嵌套层数。  
- **测试覆盖**：需验证负数、多层嵌套（如 `"[1,[2,[3]]]"`）、空列表等场景。

**总结**：通过栈动态管理嵌套层级，结合字符扫描与数值解析，可高效、安全地完成反序列化。核心在于将字符串的线性遍历与树形结构的构建解耦，确保代码简洁且可扩展。'),
