这道题是 LeetCode 第 15 题（3Sum），核心考点是**排序 + 双指针**。

**1. 复杂度分析**
*   **时间复杂度**：O(N^2)。排序耗时 O(N log N)，外层循环 N 次，内层双指针 O(N)。
*   **空间复杂度**：O(1) 或 O(logN)，取决于排序算法的空间开销。

**2. 核心思路：为什么用双指针？**
暴力法枚举三元组是 O(N^3)，超时。
**怎么做**：
1.  **排序**：先对数组排序。这使得我们可以通过数值大小判断指针移动方向，也方便去重。
2.  **固定 + 双指针**：遍历数组固定 `nums[i]`，在剩余区间 `[i+1, n-1]` 使用 `left` 和 `right` 指针寻找另外两个数。
    *   若 `sum < 0`，说明和太小，`left` 右移增大和。
    *   若 `sum > 0`，说明和太大，`right` 左移减小和。
    *   若 `sum == 0`，记录结果并移动指针。

**3. 关键细节：去重与剪枝**
*   **去重**：
    *   **外层**：若 `nums[i] == nums[i-1]`，跳过，避免第一个数重复。
    *   **内层**：找到解后，`left` 和 `right` 需跳过所有重复值，避免结果重复。
*   **剪枝**：若 `nums[i] > 0`，因数组有序，后续不可能凑出和为 0，直接 `break`。

**4. 指针移动示意**
```text
Array: [-4, -1, -1, 0, 1, 2]
       ^i    ^l           ^r
       Fixed  Left        Right
       
       If sum < 0: l ->
       If sum > 0: r <-
```

**5. 代码逻辑（Python）**
```python
nums.sort()
res = []
for i in range(len(nums)):
    if nums[i] > 0: break          # 剪枝
    if i > 0 and nums[i] == nums[i-1]: continue # 去重
    l, r = i + 1, len(nums) - 1
    while l < r:
        s = nums[i] + nums[l] + nums[r]
        if s == 0:
            res.append([nums[i], nums[l], nums[r]])
            while l < r and nums[l] == nums[l+1]: l += 1 # 去重
            while l < r and nums[r] == nums[r-1]: r -= 1
            l += 1; r -= 1
        elif s < 0: l += 1
        else: r -= 1
return res
```

**总结**：通过排序将问题降维，利用双指针将 O(N^3) 优化至 O(N^2)，面试中需重点强调**去重逻辑**的严谨性。'),
