### 和最大的连续子数组（动态规划O(n)解法）

**1. 问题本质与动态规划适用性**  
- **为什么用动态规划？**  
  该问题具有**最优子结构**：以第i个元素结尾的最大连续子数组和，可由前i-1个元素的最优解推导。同时满足**无后效性**：当前状态仅依赖前一个状态，无需历史信息。  
- **怎么做？**  
  定义状态`dp[i]`表示以`nums[i]`结尾的最大连续子数组和，通过状态转移方程逐步计算全局最大值。

**2. 状态转移方程与空间优化**  
- **为什么优化空间？**  
  原始DP需O(n)空间存储`dp`数组，但实际只需前一个状态`prev_max`，可压缩至O(1)空间。  
- **怎么做？**  
  状态转移方程：  
  `dp[i] = max(nums[i], dp[i-1] + nums[i])`  
  优化后代码逻辑：  
  ```python
  def maxSubArray(nums):
      prev_max = nums[0]  # 前一个状态
      global_max = nums[0]  # 全局最大值
      for i in range(1, len(nums)):
          prev_max = max(nums[i], prev_max + nums[i])  # 状态转移
          global_max = max(global_max, prev_max)       # 更新全局最大值
      return global_max
  ```

**3. 边界处理与关键点**  
- **为什么需处理全负数？**  
  若数组全为负数，最大和应为最大单个元素（如`[-2, -1]`结果为`-1`），而非0。  
- **怎么做？**  
  初始化`global_max`和`prev_max`为`nums[0]`，确保覆盖全负数场景。

**4. 时间复杂度分析**  
- **为什么O(n)？**  
  仅需一次遍历数组，每个元素处理时间O(1)，总时间O(n)。  
- **怎么做？**  
  通过单次循环完成状态转移，避免嵌套循环。

**总结**：动态规划通过状态转移将问题分解为局部最优解，结合空间优化实现O(n)时间、O(1)空间的高效解法。关键是通过`prev_max`记录前序状态，并实时更新全局最大值。'),
