### 三数之和（代码手撕）参考答案  

**问题分析**  
题目要求从数组中找出所有不重复的三元组，使其和为0。核心难点在于**去重**和**高效查找**。直接暴力枚举时间复杂度为O(n³)，无法满足大数据场景需求（如滴滴实时数据处理），需优化至O(n²)。  

---

#### 1. **为什么排序 + 双指针？**  
- **为什么**：排序后数组有序，可通过双指针动态调整搜索范围，避免无效遍历。例如，若当前三元组和大于0，需减小右指针；反之增大左指针。  
- **怎么做**：  
  ```python
  nums.sort()  # 排序是双指针的前提
  ```  
  固定第一个数`nums[i]`，用双指针`left=i+1`和`right=len(nums)-1`在剩余区间查找两数之和为`-nums[i]`。  

---

#### 2. **如何避免重复三元组？**  
- **为什么**：输入数组可能含重复值（如`[-1,0,1,2,-1,-4]`），直接输出会生成重复结果（如`[-1,0,1]`出现两次）。  
- **怎么做**：  
  - **外层去重**：若`nums[i] == nums[i-1]`，跳过当前`i`（避免重复固定相同值）。  
  - **内层去重**：双指针移动时，若`nums[left] == nums[left+1]`或`nums[right] == nums[right-1]`，跳过重复值。  
  ```python
  if i > 0 and nums[i] == nums[i-1]: continue  # 外层去重
  while left < right:
      if nums[left] + nums[right] == target:
          res.append([nums[i], nums[left], nums[right]])
          while left < right and nums[left] == nums[left+1]: left += 1  # 内层去重
          while left < right and nums[right] == nums[right-1]: right -= 1
          left += 1; right -= 1
  ```

---

#### 3. **复杂度与优化**  
- **时间复杂度**：O(n²)。排序O(n log n) + 双指针遍历O(n²)。  
- **空间复杂度**：O(1)（不计结果存储）。  
- **优化点**：  
  - 若`nums[i] > 0`，直接`break`（后续数均为正，无法凑和为0）。  
  - 双指针相遇时提前终止循环。  

---

#### 4. **实际场景应用**  
在滴滴数据开发中，此类算法可用于**实时订单异常检测**：例如从海量订单金额中快速定位三笔金额之和为0的异常组合（如退款+支付+手续费抵消）。通过排序+双指针，可在秒级响应内处理百万级数据。  

---

**总结**：排序奠定基础，双指针压缩搜索空间，去重逻辑保障结果唯一性。代码需兼顾效率与边界处理，体现工程化思维。'),
