### 01背包问题参考答案（算法岗面试）

---

#### **1. 问题本质与动态规划选择**  
**为什么用DP？**  
01背包具有**最优子结构**（当前最优解依赖子问题最优解）和**重叠子问题**（同一容量下的物品组合被重复计算），适合用动态规划避免指数级暴力搜索。  

**怎么做？**  
定义状态 `dp[i][j]` 表示前 `i` 个物品在容量 `j` 下的最大价值。通过逐层递推，将问题分解为更小的子问题。

---

#### **2. 状态转移方程**  
**为什么这样设计？**  
每个物品只有两种选择：**取**（需满足容量）或**不取**。转移方程需覆盖这两种情况的最大值。  

**怎么做？**  
```python
dp[i][j] = max(
    dp[i-1][j],  # 不取第i个物品
    dp[i-1][j - w[i]] + v[i]  # 取第i个物品（需 j >= w[i]）
)
```
**关键点**：  
- `w[i]` 和 `v[i]` 是第 `i` 个物品的重量和价值。  
- 若 `j < w[i]`，则无法取，直接继承 `dp[i-1][j]`。

---

#### **3. 初始化与边界条件**  
**为什么需要初始化？**  
确保基础情况正确，避免越界或逻辑错误。  

**怎么做？**  
- `dp[0][j] = 0`（无物品时价值为0）  
- `dp[i][0] = 0`（容量为0时无法取物品）  
- 实际实现中可省略显式初始化，通过循环范围控制。

---

#### **4. 空间优化（降维）**  
**为什么优化？**  
二维数组空间复杂度为 `O(n*W)`，当 `n` 或 `W` 较大时浪费内存。  

**怎么做？**  
用一维数组 `dp[j]` 替代，**逆序遍历容量**避免覆盖数据：  
```python
for i in range(1, n+1):
    for j in range(W, w[i]-1, -1):  # 逆序防止重复选取
        dp[j] = max(dp[j], dp[j - w[i]] + v[i])
```
**关键点**：  
- 逆序保证 `dp[j - w[i]]` 是上一轮的结果（未受当前物品影响）。  
- 顺序遍历会导致完全背包问题（可重复选取）。

---

#### **5. 复杂度分析**  
- **时间复杂度**：`O(n*W)`（两层循环）。  
- **空间复杂度**：`O(W)`（优化后）。  
**适用场景**：当 `W` 较小（如 ≤ 10^4）时高效，否则需考虑其他方法（如贪心近似）。

---

#### **6. 实际应用场景**  
**为什么重要？**  
01背包是资源分配的经典模型，例如：  
- **项目选择**：预算有限时选择ROI最高的项目组合。  
- **广告排期**：在固定时长内选择价值最高的广告组合。  

**代码示例**：  
```python
def knapsack_01(W, weights, values):
    dp = [0] * (W + 1)
    for w, v in zip(weights, values):
        for j in range(W, w - 1, -1):
            dp[j] = max(dp[j], dp[j - w] + v)
    return dp[W]
```

---

### **总结**  
01背包的核心是**状态定义**和**转移逻辑**，空间优化需注意遍历顺序。面试中建议先手写二维DP代码，再逐步优化，体现对算法细节的掌控。'),
