### 大数字符串相乘算法参考答案（Java）

**核心思路**：模拟小学数学竖式乘法，通过数组存储中间结果避免溢出。  
**为什么用数组？** 字符串不可变，频繁拼接效率低；数组支持按位运算，便于处理进位。

#### 1. **预处理与初始化**
   - **为什么**：需确定结果最大长度（m位数×n位数 ≤ m+n位），避免动态扩容。
   - **怎么做**：  
     ```java
     int m = num1.length(), n = num2.length();
     int[] res = new int[m + n]; // 存储每位乘积（含进位）
     ```

#### 2. **逐位相乘与进位处理**
   - **为什么**：从右向左遍历（低位优先），符合乘法进位逻辑。
   - **怎么做**：  
     ```java
     for (int i = m - 1; i >= 0; i--) {
         for (int j = n - 1; j >= 0; j--) {
             int mul = (num1.charAt(i) - ''0'') * (num2.charAt(j) - ''0'');
             int p1 = i + j, p2 = i + j + 1; // p1=高位索引, p2=低位索引
             int sum = mul + res[p2];        // 累加当前位结果
             res[p2] = sum % 10;             // 存个位
             res[p1] += sum / 10;            // 进位到高位
         }
     }
     ```

#### 3. **结果转换与去前导零**
   - **为什么**：数组首位可能为0（如"012"），需清理。
   - **怎么做**：  
     ```java
     StringBuilder sb = new StringBuilder();
     for (int x : res) if (!(sb.length() == 0 && x == 0)) sb.append(x);
     return sb.length() == 0 ? "0" : sb.toString();
     ```

#### 4. **复杂度分析**
   - **时间**：O(m×n)，双重循环遍历所有数位。  
   - **空间**：O(m+n)，结果数组固定大小。  
   - **优化点**：若输入含前导零（如"00123"），可先预处理去除，但题目未明确时需兼容。

#### 5. **边界场景验证**
   - **示例**：`"123" × "45"`  
     ```
     123
   ×  45
   -----
     615  ← 123×5
    492   ← 123×4（左移1位）
   -----
    5535
     ```
     数组变化：`[0,0,0,0] → [0,5,5,3,5]` → 输出`"5535"`。

**总结**：此解法通过数组模拟手工乘法，兼顾效率与可读性。面试中可强调**进位逻辑**和**索引计算**（`p1/p2`），体现对底层细节的掌控力。若时间充裕，可补充处理负数或非法输入的鲁棒性设计。'),
