### 参考答案

**问题分析**  
本题核心难点在于处理括号嵌套优先级、负号符号传递及空格干扰。括号会改变运算顺序，负号可能出现在表达式开头或括号后（如`- (3+2)`），需动态维护当前符号状态。

**解题思路**  
采用**栈保存中间状态**：遇到左括号时，将当前结果和符号压栈，重置计算上下文处理括号内表达式；右括号弹出栈顶状态，合并结果。符号通过`sign`变量传递，数字解析需处理连续字符。

**具体步骤**  
1. **初始化变量**  
   `res=0`（当前结果）、`sign=1`（当前符号，1表示+，-1表示-）、`stack`（保存历史状态）。  
   *为什么*：需动态记录括号外的运算状态，括号内独立计算后合并。

2. **遍历字符串**  
   - **数字**：累加解析连续数字（如`123`→`123`）。  
     *怎么做*：`num = num*10 + (c-''0'')`，避免多次转换。  
   - **`+`/`-`**：更新`sign`为`1`或`-1`，将当前`res`乘以`sign`累加到结果。  
     *为什么*：符号作用于后续数字，需提前记录。  
   - **`(`**：压栈当前`res`和`sign`，重置`res=0`、`sign=1`。  
     *怎么做*：`stack.push(res); stack.push(sign); res=0; sign=1;`  
   - **`)`**：弹出栈顶`sign`和`prev_res`，合并结果。  
     *怎么做*：`res = prev_res + sign * res;`  

3. **ASCII 状态流转示例**  
```
输入: "3+ (4-5)"  
栈操作:  
3 → res=3, sign=1  
+ → res=3, sign=1  
( → 栈:[3,1], res=0, sign=1  
4 → res=4, sign=1  
- → res=4, sign=-1  
5 → res=4-5=-1  
) → 弹出栈顶1和3 → res=3 + 1*(-1)=2  
```

**代码关键片段**  
```java
Stack<Integer> stack = new Stack<>();
int res = 0, sign = 1, num = 0;
for (char c : s.toCharArray()) {
    if (Character.isDigit(c)) {
        num = num * 10 + (c - ''0'');
    } else if (c == ''+'') {
        res += sign * num;
        sign = 1; num = 0;
    } else if (c == ''-'') {
        res += sign * num;
        sign = -1; num = 0;
    } else if (c == ''('') {
        stack.push(res); stack.push(sign);
        res = 0; sign = 1;
    } else if (c == '')'') {
        res += sign * num;
        res *= stack.pop(); // 弹出符号
        res += stack.pop(); // 弹出之前结果
        num = 0;
    }
}
return res + sign * num; // 处理末尾数字
```

**复杂度分析**  
- 时间：O(n)，单次遍历字符串。  
- 空间：O(n)，栈最坏存储所有括号状态。  

**总结**  
通过栈动态管理括号层级和符号传递，结合数字解析与符号实时更新，可高效处理嵌套表达式。关键在于分离括号内外计算上下文，避免重复解析。'),
