### 参考答案
首先我会先和面试官确认题目中「和谐子串」的定义，通常该题的和谐子串指：子串内所有字符的出现次数的最大值与最小值之差不超过1，字符集为小写字母。我的解题思路分两层：
1. **基础暴力解法**：枚举所有可能的左右端点，对每个子串统计字符频次，判断是否满足和谐条件，时间复杂度O(n²*26)，适合n≤1000的场景，代码实现简单，能快速验证逻辑正确性。
2. **优化解法（核心考点）**：利用字符集仅26个的特点，枚举左端点l，右端点r从l向右滑动，动态维护当前子串的字符频次、最大频次maxf、最小非零频次minf、频次计数数组（记录每个频次对应的字符数量），每次r右移时更新相关变量，O(1)完成和谐判断，总时间复杂度O(n²)，空间O(1)，可支持n≤5000的规模。
核心代码逻辑如下：
```cpp
int res = 0;
for(int l=0; l<n; l++){
    vector<int> freq(26,0), cnt(26,0);
    int maxf=0, minf=0, nonZero=0;
    for(int r=l; r<n; r++){
        int c = s[r]-''a'';
        if(freq[c]==0) nonZero++;
        cnt[freq[c]]--;
        freq[c]++;
        cnt[freq[c]]++;
        maxf = max(maxf, freq[c]);
        if(freq[c]==1) minf=1;
        else if(cnt[minf]==0) minf++;
        if(maxf - minf <=1) res++;
    }
}
```
如果字符集扩大或n达到1e4以上，可改用哈希表记录频次组合的哈希值，或者用莫队算法优化到O(n√n)。该算法可应用于文本均匀子串统计、密码强度检测等场景。'),
