### 参考答案

**问题分析与核心思路**  
本题需通过建造照明塔使某空点光照等级≥L，且总成本最低。关键点在于：  
1. **切比雪夫距离特性**：光照区域为正方形，半径r的塔覆盖(2r+1)²个点，但目标点本身不可放置塔（需为空点）。  
2. **有效位置限制**：每个塔类型i的实际可用数量为`min(a_i, (2r_i+1)² - 1)`（减去目标点）。  
3. **贪心策略**：因所有塔对目标点贡献相同（+1光照），优先选择单价最低的塔类型，直至满足L个塔的需求。

---

**解决步骤**  
1. **计算有效塔数量**  
   对每种塔类型i，计算其可放置的最大数量：  
   ```python
   valid_count = min(a_i, (2*r_i + 1)**2 - 1)  # 排除目标点
   ```
   *例如*：若r=1，则覆盖9个点，扣除目标点后最多放8座塔。

2. **贪心选择**  
   - 将塔类型按单价`v_i`升序排序。  
   - 依次选取最便宜的塔，直到累计数量≥L。  
   ```python
   available = sorted([(v_i, valid_count_i) for ...])  # 按v_i排序
   total = 0; cost = 0
   for v, cnt in available:
       take = min(cnt, L - total)
       cost += take * v
       total += take
       if total >= L: break
   ```

3. **边界处理**  
   - 若所有`valid_count`总和 < L，返回-1（无法达成）。  
   - 若L=0，直接返回0（无需建造）。

---

**复杂度与优化**  
- **时间复杂度**：O(n log n)（排序主导）。  
- **空间复杂度**：O(n)（存储有效塔列表）。  
- **关键优化**：无需枚举具体坐标，仅需统计数量，避免组合爆炸。

---

**示例验证**  
输入：`n=2, L=3`，塔类型：  
- 类型1：r=1, v=2, a=5 → valid_count=8  
- 类型2：r=0, v=3, a=2 → valid_count=0（r=0时仅覆盖目标点，不可用）  
**输出**：选3座类型1塔，总成本=6。

---

**总结**  
本题通过数学建模将几何问题转化为贪心选择，核心是识别有效位置限制并利用单价排序。需注意目标点不可放置塔的隐含条件，否则会导致错误。'),
