### 参考答案

**1. 问题建模与状态设计**  
- **为什么**：成就达成需满足特定条件（如点亮所有灯），需将问题转化为状态空间搜索。例如，用位掩码`mask`表示已点亮的灯集合，`pos`表示当前位置。  
- **怎么做**：定义`dp[mask][pos]`为当前状态下到达位置`pos`的最小花费。若灯数量为`K`，则状态空间为`2^K × N`（`N`为位置数）。例如，`dp[0b11][2]`表示前两个灯已点亮且位于位置2的最小成本。  

**2. 算法选择与优化**  
- **为什么**：Dijkstra算法适合处理非负权重路径问题，优先队列可避免无效状态扩展。  
- **怎么做**：  
  ```cpp
  priority_queue<pair<long long, pair<int, int>>> pq; // (cost, mask, pos)
  dp[0][start] = 0; 
  pq.push({0, {0, start}});
  while (!pq.empty()) {
      auto [cost, mask, pos] = pq.top(); pq.pop();
      if (cost > dp[mask][pos]) continue;
      for (auto next_pos : neighbors(pos)) {
          int new_mask = mask | (1 << get_lamp_id(next_pos));
          if (dp[new_mask][next_pos] > cost + edge_cost(pos, next_pos)) {
              dp[new_mask][next_pos] = cost + edge_cost(pos, next_pos);
              pq.push({dp[new_mask][next_pos], {new_mask, next_pos}});
          }
      }
  }
  ```  
  若`dp[(1<<K)-1][any_pos]`仍为无穷大，则输出`-1`。

**3. 大数处理与边界条件**  
- **为什么**：题目提示结果可能超32位整数，需用`long long`；需判断是否存在可行路径。  
- **怎么做**：初始化`dp`数组为`LLONG_MAX`，最终检查目标状态是否可达。例如：  
  ```cpp
  long long min_cost = LLONG_MAX;
  for (int pos = 0; pos < N; ++pos)
      min_cost = min(min_cost, dp[(1<<K)-1][pos]);
  return min_cost == LLONG_MAX ? -1 : min_cost;
  ```

**4. 实际场景优化**  
- **为什么**：若灯数量`K`较大（如>20），状态空间爆炸，需剪枝。  
- **怎么做**：提前终止已点亮的灯数不足的路径，或使用双向搜索。例如，仅扩展`mask`中至少新增一盏灯的状态。

**总结**：通过状态压缩+Dijkstra，结合大数处理与剪枝策略，可高效求解最小花费。若目标状态不可达则返回`-1`。'),
  ('other-347', '

### 参考答案

#### 1. **问题建模与分层策略**  
**为什么分层？**  
切比雪夫距离下，半径为 $ r $ 的光照塔覆盖范围是边长为 $ 2r+1 $ 的正方形。若直接处理所有半径，会导致大半径塔覆盖小半径区域时冗余浪费。**分层处理**可将问题拆解为：从大到小枚举半径 $ r $，确保每层 $ r $ 的需求被最小代价满足，同时利用大半径塔的覆盖优势。  

**怎么做？**  
- 将塔按半径降序排序，优先处理大半径塔（覆盖范围更广）。  
- 对每个半径 $ r $，统计该层需覆盖的点数 $ \text{points}[r] $，用优先队列维护当前可用塔的最小造价。  

---

#### 2. **贪心策略与优先队列**  
**为什么用最小堆？**  
贪心选择当前层可用的最小造价塔，能保证局部最优解累积为全局最优。**优先队列**可高效动态维护候选塔集合，避免重复计算。  

**怎么做？**  
- 遍历半径 $ r $ 从大到小：  
  1. 将半径 $ \geq r $ 的塔加入最小堆（按造价排序）。  
  2. 从堆中弹出 $ \text{points}[r] $ 个最小造价塔，覆盖当前层需求。  
- 若堆为空但仍有未覆盖点，直接返回无解。  

**代码示例**：  
```python
import heapq

def min_cost(towers, points):
    towers.sort(key=lambda x: -x.radius)  # 按半径降序
    heap = []
    total_cost = 0
    for r in sorted(points.keys(), reverse=True):
        # 将半径 >= r 的塔加入堆
        while towers and towers[-1].radius >= r:
            heapq.heappush(heap, towers.pop().cost)
        # 覆盖当前层需求
        for _ in range(points[r]):
            if not heap:
                return -1  # 无解
            total_cost += heapq.heappop(heap)
    return total_cost
```

---

#### 3. **无解判断与边界处理**  
**为什么需判断无解？**  
若某层 $ r $ 的 $ \text{points}[r] $ 超过当前堆中塔的数量，说明无法覆盖所有点。  

**怎么做？**  
- 在每层处理时，检查堆是否为空。若空且仍有未覆盖点，立即返回 `-1`。  
- 示例：若 $ \text{points}[2] = 3 $ 但堆中仅有 2 个塔，直接判定无解。  

---

#### 4. **复杂度与优化**  
**时间复杂度**：$ O(N \log N + M \log K) $，其中 $ N $ 为塔数，$ M $ 为总点数，$ K $ 为堆最大容量。  
**空间复杂度**：$ O(N) $，用于存储塔和堆。  
**优化点**：通过半径分层和贪心选择，避免暴力枚举所有组合，显著提升效率。  

---

**总结**：本题通过分层贪心+优先队列，将覆盖问题转化为动态选择最小代价塔的过程，兼顾正确性与效率，是典型的“局部最优推导全局最优”场景。'),
