### 斐波那契数列实现方案（Java）

#### 1. **递归法（基础实现）**  
**为什么用**：代码直观，符合数学定义，适合小规模输入。  
**怎么做**：直接按公式 `F(n) = F(n-1) + F(n-2)` 实现，但存在重复计算问题。  
```java
public int fib(int n) {
    if (n <= 1) return n; // 边界条件：F(0)=0, F(1)=1
    return fib(n-1) + fib(n-2);
}
```  
**问题**：时间复杂度 O(2ⁿ)，空间复杂度 O(n)（调用栈）。例如 `n=50` 会栈溢出，且大量重复计算（如 `F(3)` 被多次调用）。

---

#### 2. **迭代法（推荐方案）**  
**为什么用**：避免递归开销，空间优化至 O(1)，适合实际场景。  
**怎么做**：用两个变量滚动存储前两项，逐步计算当前值。  
```java
public int fib(int n) {
    if (n <= 1) return n;
    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}
```  
**优势**：时间 O(n)，空间 O(1)。例如 `n=5` 时，循环 3 次即可得到结果，无冗余计算。

---

#### 3. **动态规划（记忆化递归）**  
**为什么用**：保留递归逻辑，通过缓存消除重复计算。  
**怎么做**：用 `HashMap` 存储已计算结果，避免重复递归。  
```java
Map<Integer, Integer> memo = new HashMap<>();
public int fib(int n) {
    if (n <= 1) return n;
    if (memo.containsKey(n)) return memo.get(n);
    int result = fib(n-1) + fib(n-2);
    memo.put(n, result);
    return result;
}
```  
**权衡**：时间 O(n)，空间 O(n)。适合需保留递归结构的场景，但迭代法更简洁。

---

### 总结  
- **小数据量**：递归法快速验证逻辑。  
- **生产环境**：优先迭代法，平衡性能与可读性。  
- **扩展场景**：若需频繁查询不同 `n` 值，可用动态规划缓存结果。  
**关键点**：明确场景需求，避免过度设计（如 `n` 较大时注意整数溢出，可改用 `long` 类型）。'),
  ('other-352', '

### 斐波那契数列优化方案（Java）

#### 1. **递归法（基础实现）**  
**问题**：  
- **为什么低效**：递归存在大量重复计算，如计算 `fib(5)` 时会重复计算 `fib(3)` 和 `fib(2)`，时间复杂度为 O(2ⁿ)。  
- **代码示例**：  
  ```java
  int fib(int n) {
      if (n <= 1) return n;
      return fib(n-1) + fib(n-2); // 重复计算导致指数级耗时
  }
  ```

---

#### 2. **记忆化递归（动态规划）**  
**优化思路**：  
- **为什么有效**：通过缓存已计算结果避免重复计算，时间复杂度降至 O(n)。  
- **怎么做**：  
  - 使用数组或 `HashMap` 存储中间结果。  
  - **代码示例**：  
    ```java
    int[] memo;
    int fib(int n) {
        if (n <= 1) return n;
        if (memo[n] != 0) return memo[n]; // 缓存命中
        return memo[n] = fib(n-1) + fib(n-2); // 存储结果
    }
    ```

---

#### 3. **迭代法（空间优化）**  
**进一步优化**：  
- **为什么更优**：避免递归栈开销，空间复杂度从 O(n) 降至 O(1)。  
- **怎么做**：  
  - 用两个变量保存前两项，循环更新。  
  - **代码示例**：  
    ```java
    int fib(int n) {
        if (n <= 1) return n;
        int a = 0, b = 1, temp;
        for (int i = 2; i <= n; i++) {
            temp = a + b;
            a = b; 
            b = temp; // 滚动更新
        }
        return b;
    }
    ```

---

#### 4. **矩阵快速幂（大数场景）**  
**终极优化**：  
- **为什么适用**：通过数学变换将问题转化为矩阵乘法，时间复杂度降至 O(log n)，适合超大 `n`。  
- **怎么做**：  
  - 利用公式 `[[1,1],[1,0]]^n = [[fib(n+1), fib(n)],[fib(n), fib(n-1)]]`。  
  - **代码示例**：  
    ```java
    int fib(int n) {
        if (n <= 1) return n;
        int[][] M = {{1,1}, {1,0}};
        matrixPow(M, n-1); // 快速幂计算矩阵幂
        return M[0][1]; // 结果在矩阵中
    }
    ```

---

#### 总结与场景选择  
| 方法          | 时间复杂度 | 空间复杂度 | 适用场景               |  
|---------------|------------|------------|------------------------|  
| 递归          | O(2ⁿ)      | O(n)       | 仅教学演示             |  
| 记忆化递归    | O(n)       | O(n)       | 中等规模数据           |  
| 迭代法        | O(n)       | O(1)       | **通用最优解**         |  
| 矩阵快速幂    | O(log n)   | O(1)       | 超大 `n`（如 n=10⁶）   |  

**面试建议**：  
- 优先展示迭代法（简洁高效），再补充矩阵快速幂体现深度。  
- 强调实际场景权衡：如 `n < 1000` 用迭代，`n > 10⁶` 用矩阵快速幂。'),
