### 二叉树遍历参考答案

**1. 核心遍历方式及场景**  
二叉树遍历分为**前序（根左右）、中序（左根右）、后序（左右根）和层序（按层访问）**。  
- **为什么重要**：不同遍历对应不同业务需求，如前序用于序列化、中序用于BST排序、后序用于释放资源。  
- **怎么做**：  
  ```java
  // 前序递归示例
  void preorder(TreeNode root) {
      if (root == null) return;
      System.out.print(root.val + " "); // 根
      preorder(root.left);             // 左
      preorder(root.right);            // 右
  }
  ```

**2. 递归 vs 迭代实现**  
- **递归**：代码简洁，但可能栈溢出（深度过大时）。  
  **为什么用递归**：逻辑直观，适合树结构天然递归特性。  
- **迭代**：用栈/队列显式控制流程，避免栈溢出。  
  **怎么做**：  
  ```java
  // 前序迭代（栈模拟）
  void preorderIterative(TreeNode root) {
      Stack<TreeNode> stack = new Stack<>();
      while (root != null || !stack.empty()) {
          while (root != null) {
              System.out.print(root.val + " ");
              stack.push(root);
              root = root.left;
          }
          root = stack.pop().right;
      }
  }
  ```

**3. 层序遍历（BFS）**  
- **为什么用队列**：需按层访问，队列天然保证FIFO顺序。  
- **怎么做**：  
  ```java
  void levelOrder(TreeNode root) {
      Queue<TreeNode> queue = new LinkedList<>();
      queue.add(root);
      while (!queue.isEmpty()) {
          TreeNode node = queue.poll();
          System.out.print(node.val + " ");
          if (node.left != null) queue.add(node.left);
          if (node.right != null) queue.add(node.right);
      }
  }
  ```
  **ASCII流程**：  
  ```
  初始队列: [root] 
  -> 出队root，入队left/right -> 队列: [left, right]
  -> 出队left，入队其子节点...
  ```

**4. 复杂度与优化**  
- **时间复杂度**：O(n)，需访问所有节点。  
- **空间复杂度**：递归O(h)（h为树高），迭代O(n)（最坏情况）。  
- **优化场景**：若树极不平衡（如链表），迭代更安全；层序遍历可结合队列优化内存。

**总结**：根据场景选遍历方式，递归适合快速实现，迭代适合生产环境稳定性，层序遍历解决分层问题。'),
  ('other-354', '

针对“通过 tag 字段对数组进行分类和聚合展示”的问题，核心思路是利用**哈希表（Map）进行分组聚合**。以下是我的回答方案：

### 1. 核心方案：哈希分组
**为什么：** 数组遍历是线性的，若每次查找分类都要遍历，复杂度会升至 O(N²)。使用 Map 可以将 tag 作为 Key，列表作为 Value，实现 O(1) 的插入和查找，整体时间复杂度控制在 **O(N)**。
**怎么做：**
1.  初始化一个 `Map<String, List<Item>>`。
2.  遍历原始数据数组，提取 `tag` 字段。
3.  将 Item 放入 Map 中对应 tag 的 List 里。
4.  最后将 Map 转换为前端需要的展示结构（如 List 或 JSON）。

### 2. 代码实现（Java 8 Stream）
在实际开发中，推荐使用 Java 8 的 Stream API，代码更简洁且易于维护：
```java
Map<String, List<Item>> grouped = items.stream()
    .collect(Collectors.groupingBy(
        Item::getTag, 
        LinkedHashMap::new, // 保持插入顺序
        Collectors.toList()
    ));
```
**关键点：** 使用 `LinkedHashMap` 可以保留 tag 出现的原始顺序，避免展示时分类乱序。

### 3. 优化与边界处理
*   **排序需求：** 若需按 tag 字母排序，可在聚合后对 Map 的 Key 进行 `sort`；若需按列表内时间排序，可在 `Collectors.toList()` 前加 `sorted()`。
*   **空值处理：** 需过滤 `tag == null` 的数据，或将其归入“未分类”桶，防止 NPE。
*   **性能考量：** 若数据量极大（百万级），建议在数据库层通过 `GROUP BY` 完成聚合，后端仅做传输，减少内存消耗。

### 4. 数据流转示意
```text
[Raw Data Array] 
       |
       v (遍历 + 聚合)
[Map<String, List<Item>>] 
       |
       v (转换展示结构)
[Display Structure] -> Frontend Render
```

**总结：** 该方案兼顾了性能与代码可读性，通过 Map 分组解决聚合问题，结合 Stream API 提升开发效率，并考虑了排序与空值等工程细节。'),
