### RRF（Reciprocal Rank Fusion）算法参考答案

**1. 算法定义与核心思想**  
RRF是一种用于多路召回结果融合的排序算法，通过**倒数排名加权求和**整合不同来源的候选集。  
- **为什么需要RRF？**  
  多路召回（如语义检索、关键词匹配）输出的分数尺度不一致，直接加权易受单一策略偏差影响。RRF通过排名而非原始分数融合，避免量纲问题。  
- **怎么做？**  
  对每个召回源的结果按排名计算贡献值：`score = 1 / (k + rank)`，其中`k`为平滑参数（通常取60），`rank`为候选项在该召回源中的位置。最终按总分降序排序。  

**2. 公式与计算逻辑**  
RRF的数学表达为：  
```math
RRF(item) = \sum_{i=1}^{n} \frac{1}{k + rank_i(item)}
```  
- **为什么用倒数排名？**  
  排名越靠前（`rank`越小），贡献值越大，但长尾项仍保留一定权重，平衡头部与尾部信息。  
- **实际场景示例**：  
  假设召回源A返回 `[item1, item2]`，源B返回 `[item2, item3]`，`k=60`：  
  - `item1`得分 = `1/(60+1) = 0.016`  
  - `item2`得分 = `1/(60+1) + 1/(60+1) = 0.032`  
  - `item3`得分 = `1/(60+2) = 0.016`  
  最终排序：`item2 > item1 = item3`。  

**3. 优势与适用场景**  
- **为什么选择RRF？**  
  1. **无需分数归一化**：直接基于排名，避免不同模型分数分布差异；  
  2. **鲁棒性强**：对异常高分不敏感（如某召回源某项分数畸高）；  
  3. **计算高效**：仅需排名信息，适合大规模候选集。  
- **典型应用**：  
  搜索引擎多路召回融合（如ES + 向量库）、推荐系统冷启动场景。  

**4. 参数调优与局限性**  
- **k值的影响**：  
  `k`越大，长尾项权重越高（如`k=100`时`1/101` vs `1/61`）。需通过A/B测试确定最优值。  
- **局限性**：  
  无法利用召回源的置信度差异（如某源准确率显著更高），可结合加权RRF（`w_i * 1/(k+rank)`）优化。  

**流程图示例**：  
```
召回源1 → [item1, item3] → 排名列表1  
召回源2 → [item2, item1] → 排名列表2  
RRF融合 → 计算总分 → 最终排序 [item1, item2, item3]  
```  

**总结**：RRF通过简洁的排名融合机制，解决了多路召回的尺度不一致问题，是工业界广泛采用的轻量级方案。实际应用中需结合业务场景调整`k`值，并与其他策略（如加权、学习排序）互补。'),
  ('other-357', '

### 稠密检索（Dense Retrieval）的检索机制解析

**1. 核心原理：向量空间中的语义匹配**  
**为什么**：传统关键词匹配无法捕捉语义相似性（如"苹果"与"iPhone"），而稠密检索通过预训练模型将文本映射为高维向量，在向量空间中直接计算语义相似度。  
**怎么做**：采用双塔编码器（如BERT）分别生成查询和文档的固定维度向量（如768维）。例如：  
```python
query_vec = encoder(query)  # [1, 768]
doc_vec = encoder(doc)      # [1, 768]
similarity = cosine(query_vec, doc_vec)  # 余弦相似度
```
**关键优势**：支持跨语言检索（如中英混合查询）、处理同义词/多义词问题。

---

**2. 训练策略：对比学习构建语义空间**  
**为什么**：需让相似文本向量聚集、不相似文本分离，需通过对比学习显式建模语义关系。  
**怎么做**：  
- **正样本构造**：查询与相关文档对（如搜索日志中的点击记录）  
- **负样本挖掘**：硬负样本（高相似度但无关文档）提升区分度  
- **损失函数**：InfoNCE Loss 最大化正样本对概率  
```python
loss = -log(exp(sim(q,d_pos)) / Σexp(sim(q,d_neg)))
```
**实际案例**：DPR模型使用维基百科段落作为负样本库，通过在线难负样本挖掘提升效果。

---

**3. 检索流程：向量索引加速**  
**为什么**：暴力遍历文档库效率低下（如百万级文档需O(n)计算），需专用向量索引结构。  
**怎么做**：  
```mermaid
Client Query -> Encoder -> Faiss Index -> Top-K Results
|-> IVF+PQ压缩 |-> GPU加速
```
- **索引构建**：Faiss的IVF-PQ将向量分簇+乘积量化，内存占用降低10倍  
- **检索加速**：GPU并行计算，毫秒级返回Top-K结果  
**工程实践**：阿里云OpenSearch采用分布式Faiss集群，支持PB级向量实时检索。

---

**4. 优化方向：效率与效果平衡**  
- **模型蒸馏**：用教师模型（如BERT-Large）指导学生模型（如MiniLM）压缩参数  
- **动态量化**：INT8量化降低推理延迟，如Facebook的Sentence-BERT  
- **混合检索**：稠密检索+稀疏检索（BM25）融合，兼顾语义与关键词匹配  
**效果验证**：在MS MARCO数据集上，DPR+Faiss的NDCG@10达72.3%，较BM25提升15%。  

（注：ASCII图已用Mermaid语法替代，实际面试可手绘）'),
  ('other-358', '

### 参考答案：LeetCode 300. 最长递增子序列（LIS）

---

#### **1. 动态规划解法（基础版）**
**为什么选它？**  
这是最直观的解法，适合理解问题本质。通过记录以每个元素结尾的最长递增子序列长度，逐步推导全局最优解。

**怎么做？**  
- **状态定义**：`dp[i]` 表示以 `nums[i]` 结尾的 LIS 长度。  
- **转移方程**：遍历 `j < i`，若 `nums[j] < nums[i]`，则 `dp[i] = max(dp[i], dp[j] + 1)`。  
- **初始化**：所有 `dp[i] = 1`（单个元素本身构成长度为1的序列）。  
- **结果**：`max(dp)`。  

**代码示例**：
```java
public int lengthOfLIS(int[] nums) {
    if (nums.length == 0) return 0;
    int[] dp = new int[nums.length];
    Arrays.fill(dp, 1);
    for (int i = 1; i < nums.length; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    return Arrays.stream(dp).max().getAsInt();
}
```
**复杂度**：时间 O(n²)，空间 O(n)。适用于小规模数据，但无法处理大规模输入。

---

#### **2. 贪心 + 二分优化（进阶版）**
**为什么选它？**  
动态规划效率低，而贪心+二分可将时间复杂度降至 O(n log n)，适合生产环境。

**怎么做？**  
- **核心思想**：维护一个数组 `tails`，其中 `tails[i]` 存储长度为 `i+1` 的递增子序列的最小末尾值。  
- **关键操作**：  
  - 遍历每个数 `num`，若 `num > tails` 最后一个元素，则直接追加（延长序列）。  
  - 否则，用 `num` 替换 `tails` 中第一个 ≥ `num` 的元素（保持更小的末尾值，便于后续扩展）。  
- **结果**：`tails` 的长度即为 LIS 长度。  

**代码示例**：
```java
public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int len = 0;
    for (int num : nums) {
        int i = Arrays.binarySearch(tails, 0, len, num);
        if (i < 0) i = -(i + 1); // 找到插入位置
        tails[i] = num;
        if (i == len) len++;
    }
    return len;
}
```
**复杂度**：时间 O(n log n)，空间 O(n)。  
**场景**：高频面试考点，需重点掌握二分查找逻辑（`Arrays.binarySearch` 的返回值处理）。

---

#### **3. 变种问题思考（加分项）**
- **严格递增 vs 非递减**：若题目允许相等元素（如最长非递减子序列），只需将二分条件改为 `nums[j] <= nums[i]`。  
- **空间优化**：动态规划无法优化空间，但贪心法已是最优。  
- **实际应用**：股票买卖问题（如“最佳买卖时机III”）可转化为 LIS 变种。

---

#### **总结**
- **优先掌握贪心+二分**：大厂高频考点，体现算法功底。  
- **动态规划作为基础**：帮助理解问题本质，但需指出其局限性。  
- **结合场景**：例如，“若数据量达到百万级，你会如何选择？” → 直接答贪心法并解释原因。'),
