### Transformer 与自注意力机制参考答案

#### 1. **Transformer 架构优势**  
**为什么选择 Transformer？**  
传统 RNN 存在序列依赖问题（如梯度消失），CNN 难以捕捉长距离依赖。Transformer 通过**自注意力机制**实现全局上下文建模，且支持**并行计算**，显著提升训练效率。  

**怎么做？**  
采用**编码器-解码器结构**（见下图），每层包含多头自注意力、前馈网络和残差连接：  
```
Input → Embedding + Positional Encoding  
        ↓  
[Encoder Layer] × N  
  ├─ Multi-Head Self-Attention  
  ├─ Add & Norm  
  └─ Feed Forward Network  
        ↓  
[Decoder Layer] × N  
  ├─ Masked Multi-Head Self-Attention  
  ├─ Add & Norm  
  └─ Cross-Attention (Encoder Output)  
        ↓  
Output → Linear + Softmax
```

---

#### 2. **自注意力机制核心原理**  
**为什么有效？**  
自注意力通过计算序列中所有位置间的**关联权重**，动态聚焦关键信息（如“它”指向“苹果”）。相比 RNN 的逐步传递，直接建立全局依赖关系。  

**怎么做？**  
以缩放点积注意力为例（伪代码）：  
```python
def self_attention(Q, K, V):
    # 计算注意力分数并归一化
    scores = torch.matmul(Q, K.transpose(-2, -1)) / sqrt(d_k)
    attention_weights = softmax(scores, dim=-1)
    # 加权求和
    output = torch.matmul(attention_weights, V)
    return output
```
**关键点**：  
- **Q/K/V 矩阵**：通过线性投影从输入生成，分别代表查询、键、值。  
- **缩放因子**：除以 $\sqrt{d_k}$ 防止梯度消失。  
- **Mask 机制**：解码器中屏蔽未来位置信息（如训练时防止“偷看”）。

---

#### 3. **多头注意力扩展**  
**为什么需要多头？**  
单一注意力头可能忽略某些语义关系（如语法 vs 语义），多头通过**子空间并行计算**增强表达能力。  

**怎么做？**  
将 Q/K/V 分割为 $h$ 个头，独立计算后拼接：  
```
Head_i = Attention(QW_i^Q, KW_i^K, VW_i^V)
Output = Concat(Head_1,...,Head_h)W^O
```
**实际场景**：在机器翻译中，不同头可能分别关注词序、词性、语义角色。

---

#### 4. **工程实践要点**  
- **位置编码**：通过正弦/余弦函数注入位置信息（因自注意力本身无顺序感知）。  
- **残差连接+层归一化**：缓解梯度问题，加速收敛（如 `LayerNorm(x + Sublayer(x))`）。  
- **计算优化**：使用 FlashAttention 减少显存占用（分块计算注意力矩阵）。

**总结**：Transformer 通过自注意力突破序列建模瓶颈，成为 NLP/CV 通用架构。其核心在于**动态权重分配**与**并行化设计**，需结合具体任务调整头数、层数等超参数。'),
  ('other-360', '

### 自注意力机制的时间与空间复杂度分析  

#### 1. **时间复杂度：O(n²d)**  
**为什么**：  
自注意力需计算查询（Q）与键（K）的点积矩阵（QK^T），规模为n×n（n为序列长度），每个点积操作涉及d维向量（d为隐藏层维度）。后续加权求和值（V）同样需遍历n×n矩阵，因此总计算量为O(n²d)。例如，BERT处理512长度序列时，单头注意力需约26万点积运算（512²），若d=768则计算量显著放大。  

**怎么做**：  
- **优化方向**：通过低秩近似（如Linformer）将QK^T降维至O(nd²)，或采用稀疏注意力（如Longformer）仅计算局部窗口内的点积，降低复杂度至O(nd)。  
- **实际场景**：在长文本建模中，Flash Attention通过分块计算避免显存瓶颈，同时保持O(n²d)时间复杂度但提升效率。  

---

#### 2. **空间复杂度：O(n²)**  
**为什么**：  
需存储n×n的注意力矩阵（QK^T），其内存占用随序列长度平方增长。例如，1024长度序列需约1M浮点数（假设float16），对GPU显存压力显著。  

**怎么做**：  
- **优化方向**：  
  - **分块处理**：将序列划分为小块（如Flash Attention），逐块计算注意力，显存占用降至O(n·block_size)。  
  - **低秩近似**：用少量基向量近似QK^T（如Performer），空间复杂度降至O(nd)。  
- **实际场景**：视频建模中，3D注意力需处理时空维度，常结合分块策略避免显存溢出。  

---

#### 3. **核心权衡与扩展**  
- **多头注意力**：若使用h个头，复杂度线性增加至O(hn²d)，但并行计算可缓解延迟。  
- **线性注意力**：如Linformer通过随机投影将QK^T降维，时间/空间复杂度均降至O(nd²)，适用于超长序列（如Genome建模）。  

**总结**：自注意力的O(n²)瓶颈源于全局交互，优化需平衡精度与效率。工业界常结合分块、稀疏化或近似方法，在保持模型性能的同时适配资源约束。'),
