### 自注意力问题与优化方案（面试参考答案）

#### 一、自注意力的核心问题  
1. **计算复杂度过高**  
   - **为什么**：标准自注意力需计算序列中所有 token 的两两交互，复杂度为 $O(n^2)$。当序列长度 $n$ 超过 1000 时（如长文档摘要、视频帧序列），显存和计算开销会急剧上升。  
   - **怎么做**：以 1000 长度序列为例，原始注意力需 $10^6$ 次矩阵乘法，而优化后可降至 $10^4$ 级别。  

2. **信息冗余与稀疏性**  
   - **为什么**：多数 token 对实际无强关联（如长文本中相邻词相关性强，远距离词弱），但标准注意力仍强制计算全局交互，导致资源浪费。  
   - **怎么做**：通过稀疏模式（如局部窗口+全局 token）或动态筛选关键 token 减少无效计算。  

---

#### 二、主流优化方法及实现  
1. **线性注意力（如 Performer）**  
   - **原理**：用核函数近似注意力矩阵，将复杂度降至 $O(n)$。  
   - **代码示例**：  
     ```python
     # 用随机特征映射 R 近似 QK^T
     R = torch.randn(d, m)  # m 为随机投影维度
     Q_proj = torch.matmul(Q, R)  # 替代 QK^T
     ```
   - **适用场景**：长序列建模（如 DNA 序列分析），显存占用降低 90%。  

2. **稀疏注意力（如 Longformer）**  
   - **原理**：仅计算局部窗口（如±512 token）和全局 token（如 [CLS]）的注意力。  
   - **架构图**：  
     ```
     Input Tokens -> [Local Window | Global Tokens] -> Sparse Attention -> Output
     ```
   - **效果**：在 10k 长度序列上，FLOPs 降低 100 倍，适用于文档级 NLP 任务。  

3. **分块与低秩分解**  
   - **原理**：将序列分块处理（如 Reformer 的局部敏感哈希），或通过低秩矩阵分解压缩注意力权重。  
   - **实际案例**：视频理解中，对 100 帧序列分块为 10 组，每组独立计算注意力后融合，推理速度提升 5 倍。  

---

#### 三、总结  
优化核心是**平衡精度与效率**：线性方法适合超大规模序列，稀疏方法保留局部语义，分块策略适配多模态场景。选择时需结合任务特性（如序列长度、实时性要求）动态调整，例如在实时语音识别中优先采用分块+线性注意力组合方案。'),
