### 机器学习树模型核心知识点（面试参考答案）

---

#### **1. 决策树基础原理与优化**
**为什么**：  
决策树通过递归划分特征空间实现分类/回归，其可解释性强（如医疗诊断中规则透明），但对噪声敏感且易过拟合。  
**怎么做**：  
- **分裂准则**：分类用基尼系数（`Gini = 1 - Σp_i²`），回归用MSE，选择使子节点纯度最高的特征。  
- **剪枝**：预剪枝（限制深度/节点样本数）和后剪枝（代价复杂度剪枝），例如：  
  ```python
  tree = DecisionTreeClassifier(max_depth=5, min_samples_split=20)
  ```

---

#### **2. 集成方法：Bagging vs Boosting**
**为什么**：  
- **Bagging（随机森林）**：通过并行训练多棵树降低方差，适合高维数据（如推荐系统特征组合）。  
- **Boosting（GBDT/XGBoost）**：串行优化弱学习器，聚焦难样本，提升准确率。  
**怎么做**：  
- **随机森林**：每棵树随机采样数据+特征，最终投票/平均：  
  ```
  RF = (T₁ + T₂ + ... + Tₙ)/n  # 回归任务
  ```
- **GBDT**：每轮拟合前一轮残差，如：  
  ```
  F₀(x) = argmin_γ ΣL(y, γ)  
  Fₘ(x) = Fₘ₋₁(x) + ρₘ·hₘ(x)  # hₘ为新树
  ```

---

#### **3. 工业级优化：XGBoost/LightGBM**
**为什么**：  
- **XGBoost**：引入正则化（`λ||w||² + γT`）抑制过拟合，支持并行计算加速。  
- **LightGBM**：直方图算法减少分裂点搜索，Leaf-wise生长提升精度。  
**怎么做**：  
- **XGBoost参数调优**：  
  ```python
  xgb_model = XGBClassifier(
      n_estimators=100,  # 树数量
      max_depth=6,       # 控制复杂度
      learning_rate=0.1, # 步长
      subsample=0.8      # 采样比例
  )
  ```
- **LightGBM场景**：处理大规模稀疏特征（如广告点击率预测），通过`feature_fraction`减少特征维度。

---

#### **4. 实际问题解决**
**为什么**：  
树模型对类别不平衡、缺失值敏感，需针对性优化。  
**怎么做**：  
- **类别不平衡**：调整`scale_pos_weight`（XGBoost）或SMOTE采样。  
- **缺失值处理**：XGBoost自动学习最优分裂方向（如：`[missing] -> left`）。  
- **特征重要性**：通过`feature_importances_`筛选关键特征（如风控模型中“逾期次数”权重最高）。

---

**总结**：树模型从单棵到集成、从理论到工程优化，核心是平衡偏差-方差，结合业务场景选择算法（如实时性要求高用LightGBM，可解释性优先用决策树）。'),
