### 参考答案：

**1. 数据层面：调整样本分布**  
- **为什么**：类别不均衡会导致模型过度偏向多数类，忽略少数类特征。  
- **怎么做**：  
  - **过采样**：对少数类生成合成样本（如SMOTE），增加其代表性。  
  - **欠采样**：随机删除多数类样本，平衡数据量。  
  - **示例**：  
    ```python
    from imblearn.over_sampling import SMOTE  
    smote = SMOTE()  
    X_res, y_res = smote.fit_resample(X, y)  # 平衡后的数据集  
    ```  
  - **场景**：医疗诊断中阳性样本稀少，通过SMOTE提升模型对异常病例的识别能力。  

**2. 算法层面：优化损失函数与模型结构**  
- **为什么**：传统损失函数对少数类误差惩罚不足，需显式调整权重。  
- **怎么做**：  
  - **类别权重**：在损失函数中为少数类赋予更高权重（如`class_weight=''balanced''`）。  
  - **集成学习**：使用EasyEnsemble等算法组合多个平衡子集训练的模型。  
  - **示例**：  
    ```python
    from sklearn.linear_model import LogisticRegression  
    model = LogisticRegression(class_weight=''balanced'')  # 自动调整权重  
    ```  
  - **场景**：电商风控中欺诈交易占比低，通过权重调整提升召回率。  

**3. 评估指标：避免准确率误导**  
- **为什么**：准确率在极端不均衡下失效（如99%负例时，全预测负例也有99%准确率）。  
- **怎么做**：  
  - **F1-Score**：综合精确率与召回率，关注少数类表现。  
  - **AUC-PR曲线**：更敏感于少数类预测质量。  
  - **示例**：  
    ```python
    from sklearn.metrics import f1_score, average_precision_score  
    f1 = f1_score(y_true, y_pred)  
    ```  

**架构示意**：  
```
原始数据: 正例 10% | 负例 90%  
       ↓ (SMOTE过采样)  
平衡数据: 正例 50% | 负例 50%  
       ↓  
模型训练: 损失函数加权 (w_pos=9, w_neg=1)  
       ↓  
评估: F1=0.85 (优于准确率95%)  
```  

**总结**：需结合数据预处理、算法优化和评估指标改进，例如在金融反欺诈场景中，通过SMOTE+类别权重+F1评估，可将少数类召回率从30%提升至75%。'),
