### 参考答案

**1. 问题理解与目标**  
树形结构转列表的核心需求是**按层级顺序扁平化节点**（如1→2→3→4→5）。选择层序遍历（BFS）而非DFS，因为：  
- **为什么**：层序遍历天然保持树的层级关系，符合"列表需体现结构层次"的业务场景（如组织架构导出）。  
- **怎么做**：通过队列逐层处理节点，确保父节点先于子节点入列表。

---

**2. 算法设计与实现**  
```java
public List<Integer> treeToList(TreeNode root) {
    if (root == null) return new ArrayList<>();
    List<Integer> result = new ArrayList<>();
    Queue<TreeNode> queue = new LinkedList<>();
    queue.add(root);
    
    while (!queue.isEmpty()) {
        TreeNode node = queue.poll();
        result.add(node.val); // 当前节点入列表
        if (node.left != null) queue.add(node.left);  // 左子节点入队
        if (node.right != null) queue.add(node.right); // 右子节点入队
    }
    return result;
}
```
- **关键点**：  
  - 队列保证FIFO顺序，避免递归栈溢出（适合深树）。  
  - 空节点校验防止NPE，提升鲁棒性。

---

**3. 复杂度与优化**  
- **时间复杂度**：O(n)，每个节点仅入队/出队一次。  
- **空间复杂度**：O(w)，w为树的最大宽度（队列最大长度）。  
- **优化场景**：若树极宽（如完全二叉树），可改用迭代+深度标记替代队列，但需权衡代码复杂度。

---

**4. 扩展思考**  
- **变体处理**：若需保留层级信息（如[1, [2,3], [4,5]]），可改用`Map<Integer, List<Integer>>`存储层号与节点列表。  
- **实际案例**：滴滴内部曾用于将部门树结构导出为扁平化报表，通过层序遍历确保上级部门优先展示。

---

**总结**：层序遍历是平衡效率与可读性的最优解，代码简洁且易于扩展，符合工程实践需求。'),
