### 回文数动态规划问题参考答案  

**1. 问题理解与动态规划适用性**  
- **为什么用动态规划**：若题目要求将数字拆分为最少的回文数之和（如LeetCode 1249），贪心策略可能失效（例如123拆分为121+2而非111+12）。动态规划通过**子问题重叠**特性，避免重复计算，确保最优解。  
- **怎么做**：定义`dp[i]`为数字`i`的最小回文数拆分数量，状态转移方程为`dp[i] = min(dp[i - p] + 1)`，其中`p`是所有≤`i`的回文数。  

**2. 动态规划核心设计**  
- **状态定义**：`dp[i]`表示数字`i`的最小拆分数，初始化`dp[0]=0`，其余为`∞`。  
- **状态转移**：遍历所有预处理的回文数`p`，更新`dp[i]`。例如：  
  ```python
  for i in range(1, n+1):
      for p in palindromes:
          if i >= p:
              dp[i] = min(dp[i], dp[i - p] + 1)
  ```  
- **为什么预处理回文数**：直接判断每个数是否为回文数效率低，预处理可减少重复计算。  

**3. 回文数预处理优化**  
- **怎么做**：生成所有≤`n`的回文数。例如，通过数学构造（如1, 2, ..., 11, 22, ..., 121）或字符串反转验证：  
  ```python
  palindromes = [i for i in range(1, n+1) if str(i) == str(i)[::-1]]
  ```  
- **为什么高效**：回文数密度低（如1000内仅108个），预处理后遍历次数大幅减少。  

**4. 复杂度与优化**  
- **时间复杂度**：O(n * k)，`k`为回文数数量（实际远小于n）。  
- **空间复杂度**：O(n)存储`dp`数组。  
- **优化点**：仅需预处理到`√n`的回文数（如121），更高位回文数对结果影响小。  

**5. 实际场景示例**  
- **输入**：`n = 123`  
- **输出**：`3`（拆分：121 + 2）  
- **流程**：  
  ```
  dp[0] = 0  
  dp[1] = 1 (1)  
  dp[2] = 1 (2)  
  ...  
  dp[121] = 1 (121)  
  dp[123] = min(dp[123-121]+1, ...) = 2 → 最终结果3（需结合其他回文数）  
  ```  

**总结**：动态规划通过**状态压缩**和**预处理**解决回文数拆分问题，核心在于合理定义子问题并利用回文数的稀疏性优化效率。'),
