### 参考答案（结构化口头表达）

---

#### **1. 理解数组结构**  
**为什么**：数组中的每个元素通常包含 `id` 和 `parentId` 字段，需通过层级关系构建树。  
**怎么做**：  
- 假设数组元素格式为 `{id, parentId, name}`，例如：  
  ```java
  List<Map<String, Object>> list = Arrays.asList(
      Map.of("id", 1, "parentId", null, "name", "Root"),
      Map.of("id", 2, "parentId", 1, "name", "Child1"),
      Map.of("id", 3, "parentId", 2, "name", "GrandChild")
  );
  ```
- 用 `HashMap<Integer, Node>` 缓存所有节点，键为 `id`，值为节点对象。

---

#### **2. 构建树的核心逻辑**  
**为什么**：通过哈希表快速定位父节点，避免重复遍历。  
**怎么做**：  
```java
public Node buildTree(List<Map<String, Object>> list) {
    Map<Integer, Node> nodeMap = new HashMap<>();
    Node root = null;

    // 第一步：创建所有节点
    for (Map<String, Object> item : list) {
        int id = (int) item.get("id");
        Node node = new Node(id, item.get("name"));
        nodeMap.put(id, node);
    }

    // 第二步：建立父子关系
    for (Map<String, Object> item : list) {
        int id = (int) item.get("id");
        Integer parentId = (Integer) item.get("parentId");
        Node node = nodeMap.get(id);

        if (parentId == null) {
            root = node; // 根节点
        } else {
            nodeMap.get(parentId).children.add(node);
        }
    }
    return root;
}
```
**关键点**：  
- 时间复杂度 O(n)，空间复杂度 O(n)。  
- 通过 `parentId` 直接关联父节点，无需递归。

---

#### **3. 边界条件处理**  
**为什么**：需验证数据合法性，避免空指针或循环引用。  
**怎么做**：  
- 检查 `parentId` 是否存在于 `id` 列表中（如 `nodeMap.containsKey(parentId)`）。  
- 对非法输入抛出异常：  
  ```java
  if (!nodeMap.containsKey(parentId)) {
      throw new IllegalArgumentException("Invalid parentId: " + parentId);
  }
  ```

---

#### **4. 树结构示例**  
```
Root (id=1)
|-> Child1 (id=2)
    |-> GrandChild (id=3)
```
**调用链**：  
`buildTree(list) -> 创建节点 -> 关联父子关系 -> 返回根节点`

---

#### **5. 扩展思考**  
若数组无序（如 `parentId` 未出现在前序元素中），需先按 `parentId` 排序，或多次遍历确保所有父节点已创建。  

---

**总结**：通过哈希表缓存节点、分两步构建关系，兼顾效率与鲁棒性，适用于组织架构、菜单树等场景。'),
