### 最长递增子序列（LIS）算法题参考答案  

#### 1. **问题理解与核心思路**  
最长递增子序列（LIS）要求从数组中找出一个最长的子序列，使得元素严格递增。核心难点在于**如何高效维护递增性**。常见解法有两种：动态规划（O(n²)）和贪心+二分优化（O(n log n)）。  

---

#### 2. **动态规划解法（基础版）**  
**为什么用动态规划？**  
- 每个位置的最长递增子序列长度依赖于前面的结果，符合**最优子结构**和**重叠子问题**特性。  

**怎么做？**  
- 定义 `dp[i]` 表示以 `nums[i]` 结尾的 LIS 长度。  
- 状态转移方程：`dp[i] = max(dp[j] + 1)`，其中 `j < i` 且 `nums[j] < nums[i]`。  
- 最终结果为 `max(dp)`。  

**代码示例（Java）：**  
```java
public int lengthOfLIS(int[] nums) {
    if (nums.length == 0) return 0;
    int[] dp = new int[nums.length];
    Arrays.fill(dp, 1);
    for (int i = 1; i < nums.length; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    return Arrays.stream(dp).max().getAsInt();
}
```  
**复杂度：** 时间 O(n²)，空间 O(n)。适用于数据量较小的场景（如 n ≤ 1000）。  

---

#### 3. **贪心+二分优化解法（进阶版）**  
**为什么能优化？**  
- 动态规划中重复计算了“以某个值结尾的最短递增子序列长度”，可通过**维护一个递增数组 `tails`** 减少冗余。  
- `tails[i]` 表示长度为 `i+1` 的递增子序列的最小末尾元素，利用二分查找快速定位插入位置。  

**怎么做？**  
- 遍历数组，对每个元素 `num`：  
  1. 若 `num` 大于 `tails` 末尾元素，直接追加（延长 LIS）。  
  2. 否则，用二分查找找到 `tails` 中第一个 ≥ `num` 的位置并替换（保持潜在更优解）。  

**代码示例（Java）：**  
```java
public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int len = 0;
    for (int num : nums) {
        int i = Arrays.binarySearch(tails, 0, len, num);
        if (i < 0) i = -(i + 1); // 找到插入位置
        tails[i] = num;
        if (i == len) len++; // 扩展 LIS 长度
    }
    return len;
}
```  
**复杂度：** 时间 O(n log n)，空间 O(n)。适用于大数据量场景（如 n ≤ 10⁵）。  

---

#### 4. **关键对比与场景选择**  
| 方法          | 时间复杂度 | 空间复杂度 | 适用场景               |  
|---------------|------------|------------|------------------------|  
| 动态规划      | O(n²)      | O(n)       | 小规模数据，需输出具体序列 |  
| 贪心+二分     | O(n log n) | O(n)       | 大规模数据，仅需长度     |  

**实际场景举例：**  
- 若需输出具体子序列（如 `[10, 9, 2, 5, 3, 7, 101, 18]` → `[2, 3, 7, 18]`），动态规划更直观。  
- 若仅需长度（如股票价格趋势分析），贪心+二分更高效。  

---

#### 5. **总结**  
- **动态规划**是基础解法，逻辑直观但效率较低；  
- **贪心+二分**通过维护潜在最优解，显著提升性能，是工程实践中的首选。  
- 面试时可结合具体场景说明选择依据，体现对算法适用性的深度理解。'),
