### 参考答案

**核心思路**：通过**累积权重+二分查找**实现加权随机抽样，确保每个元素被选中的概率与其权重成正比。

---

#### 1. **为什么用累积权重？**
- **原理**：将权重转换为区间范围，例如权重 `[1,2,3]` 对应区间 `[0,1), [1,3), [3,6)`。生成随机数后，落在哪个区间即选择对应元素。
- **优势**：时间复杂度低（O(log n)），适合大规模数据。

#### 2. **具体实现步骤**
```go
func WeightedRandom(elements []string, weights []int, count int) []string {
    // 1. 验证输入合法性
    if len(elements) != len(weights) || len(weights) == 0 {
        panic("invalid input")
    }
    
    // 2. 计算总权重 & 构建累积权重数组
    totalWeight := 0
    cumWeights := make([]int, len(weights))
    for i, w := range weights {
        totalWeight += w
        cumWeights[i] = totalWeight
    }
    
    // 3. 生成随机结果
    result := make([]string, count)
    for i := 0; i < count; i++ {
        randNum := rand.Intn(totalWeight) // 生成 [0, totalWeight) 随机数
        idx := sort.Search(len(cumWeights), func(i int) bool {
            return cumWeights[i] > randNum // 找到首个大于随机数的位置
        })
        result[i] = elements[idx]
    }
    return result
}
```

#### 3. **关键细节说明**
- **二分查找**：`sort.Search` 快速定位区间，避免线性遍历（O(n) → O(log n)）。
- **随机数范围**：`rand.Intn(totalWeight)` 确保均匀覆盖所有权重区间。
- **边界处理**：当 `randNum` 等于累积值时（如 `randNum=3`），通过 `>` 条件正确落入下一区间。

#### 4. **实际场景优化**
- **高并发场景**：使用 `rand.New(src)` 替代全局 `rand`，避免锁竞争。
- **动态权重**：若权重频繁变化，可缓存累积数组并定期更新。

---

**示例**：  
输入 `elements=["A","B","C"], weights=[1,2,3], count=2`  
累积权重 `[1,3,6]` → 随机数 `2` 落入 `[1,3)` → 选 `B`；随机数 `5` 落入 `[3,6)` → 选 `C`。  
输出可能为 `["B","C"]`，符合权重比例（A:1/6, B:2/6, C:3/6）。

**总结**：该方法兼顾效率与准确性，适用于游戏抽卡、负载均衡等场景。'),
