### 参考答案

**1. 方法选择与原理**  
采用**中心扩展法**，核心思路是：回文串具有中心对称性，每个字符或相邻字符对可作为回文中心。  
- **为什么选此方法？**  
  相比动态规划（需O(n²)空间存储状态），中心扩展法仅需O(1)额外空间，且能直接生成所有回文子串，适合本题“找出全部回文串”的需求。  
- **怎么做？**  
  遍历字符串每个位置，分别以**单个字符**（奇数长度）和**相邻字符对**（偶数长度）为中心，向两侧扩展判断回文。

---

**2. 具体实现步骤**  
```python
def find_palindromes(s):
    res = []
    def expand(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            res.append(s[left:right+1])
            left -= 1
            right += 1
    for i in range(len(s)):
        expand(i, i)      # 奇数长度中心（如 ''a''）
        expand(i, i+1)    # 偶数长度中心（如 ''aa''）
    return res
```
- **关键点说明**：  
  - `expand`函数通过双指针向两侧扩展，每次匹配成功即记录子串。  
  - 遍历所有位置时，需同时处理奇偶中心（如输入"aba"，中心分别为`a`、`b`、`a`及`ab`、`ba`）。

---

**3. 边界与优化**  
- **边界处理**：空字符串直接返回空列表；单字符字符串返回自身。  
- **时间复杂度**：O(n²)，最坏情况下（如全相同字符）需检查所有子串。  
- **实际场景**：若需去重（如输入"aaa"），可在结果集使用集合（Set）过滤，但题目未要求时优先保证完整性。

---

**4. 测试用例验证**  
输入 `s = "aba"`：  
- 奇数中心：`a` → "a", `b` → "b", `a` → "a"  
- 偶数中心：`ab` → 无, `ba` → 无  
- 最终结果：`["a", "b", "a", "aba"]`（注意：实际输出需按题目要求排序或去重）  

此方案兼顾效率与完整性，适合面试中快速实现并解释。'),
