### 二叉树广度优先遍历（BFS）参考答案

#### 1. **算法原理与选择理由**  
广度优先遍历（BFS）通过**队列**实现逐层访问节点，符合“从左到右”的需求。  
- **为什么用队列？**  
  队列的FIFO特性天然适配层序遍历：先入队的节点先出队，确保同一层节点按顺序处理。  
- **为什么不用递归？**  
  递归更适合深度优先（DFS），而BFS需显式管理节点顺序，队列更直观且避免栈溢出风险。

#### 2. **实现步骤**  
```java
public List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> result = new ArrayList<>();
    if (root == null) return result; // 空树直接返回
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root); // 根节点入队

    while (!queue.isEmpty()) {
        int size = queue.size(); // 当前层节点数
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll(); // 出队
            level.add(node.val);          // 记录值
            if (node.left != null) queue.offer(node.left);  // 左子节点入队
            if (node.right != null) queue.offer(node.right); // 右子节点入队
        }
        result.add(level); // 保存当前层结果
    }
    return result;
}
```
- **关键点**：  
  - 用`size`控制每层遍历范围，避免混层。  
  - 先入队左子节点再入队右子节点，保证“从左到右”。

#### 3. **复杂度分析**  
- **时间复杂度**：O(n)，每个节点仅访问一次。  
- **空间复杂度**：O(n)，队列最大存储一层的节点数（最坏情况为完全二叉树的最后一层）。

#### 4. **实际场景与扩展**  
- **场景**：  
  - 树的层次遍历（如打印文档结构）。  
  - 最短路径问题（如迷宫求解）。  
- **变体**：  
  - 若需按层返回结果，需记录每层节点数（如代码中的`size`）。  
  - 若树为完全二叉树，可优化为数组模拟队列（索引计算）。

#### 5. **注意事项**  
- **空树处理**：提前判断`root == null`避免空指针。  
- **内存优化**：若仅需遍历值，可复用队列而非创建新`List`。  

**总结**：BFS通过队列实现层序遍历，核心是控制每层节点数量并严格遵循入队顺序。代码简洁且鲁棒性强，适合处理树的广度优先场景。'),
