### 岛屿数量问题参考答案

**1. 问题理解与核心目标**  
题目要求统计二维网格中由''1''（陆地）组成的岛屿数量，岛屿通过上下左右四方向连通。核心挑战在于**高效遍历所有连通区域**并避免重复计数。例如：  
```
输入: ["1100", "1010", "0110"]  
输出: 2（左上角和右下角各1个岛屿）
```

**2. 解法选择：DFS vs BFS**  
- **为什么选DFS**：递归实现更简洁，适合处理连通性问题。但需注意**递归深度限制**（如网格过大时改用BFS或迭代DFS）。  
- **怎么做**：  
  - 遍历网格，遇到''1''则启动DFS，将连通区域全部标记为''0''（避免重复访问）。  
  - 每次DFS启动计数+1，最终返回总次数。  

**3. 关键实现细节**  
```python
def numIslands(grid):
    if not grid: return 0
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == ''1'':
                dfs(grid, i, j)
                count += 1
    return count

def dfs(grid, i, j):
    if i<0 or j<0 or i>=len(grid) or j>=len(grid[0]) or grid[i][j]==''0'':
        return
    grid[i][j] = ''0''  # 标记为已访问
    dfs(grid, i+1, j)  # 上下左右递归
    dfs(grid, i-1, j)
    dfs(grid, i, j+1)
    dfs(grid, i, j-1)
```

**4. 复杂度与优化**  
- **时间复杂度**：O(m×n)，每个格子最多访问一次。  
- **空间复杂度**：O(m×n)，递归栈深度最坏为网格大小（如全为''1''时）。  
- **优化**：若网格极大，可改用**BFS+队列**避免递归栈溢出，或用**并查集**动态合并连通区域。

**5. 实际场景与扩展**  
- **应用场景**：图像分割（如卫星图中识别独立岛屿）、游戏地图生成（如《Minecraft》地形分析）。  
- **扩展思考**：若题目改为八连通（含对角线），只需在DFS中增加4个方向判断。  

**总结**：通过DFS高效遍历连通区域，结合标记机制避免重复计数，是解决此类问题的经典范式。实际开发中需根据数据规模权衡递归与迭代方案。'),
