### 0-1背包问题参考答案（算法岗）

**1. 问题本质与解法选择**  
0-1背包是经典动态规划问题：给定容量为 `W` 的背包和 `n` 个物品（每个物品仅能选一次），求最大价值。  
**为什么用DP？** 因为存在重叠子问题（不同物品组合可能共享相同剩余容量）和最优子结构（全局最优解由局部最优解构成）。贪心会失效（如高价值物品可能超重）。  

**2. 状态定义与转移方程**  
- **状态设计**：`dp[i][w]` 表示前 `i` 个物品、容量 `w` 下的最大价值。  
- **转移逻辑**：  
  ```python
  dp[i][w] = max( 
      dp[i-1][w],  # 不选第i个物品
      dp[i-1][w-weight[i]] + value[i]  # 选第i个物品（需满足 w >= weight[i]）
  )
  ```  
**为什么这样设计？** 通过枚举“选/不选”决策，覆盖所有可能性，且子问题独立可复用。  

**3. 空间优化技巧**  
- **原始二维数组**：`O(nW)` 空间，直观但浪费内存。  
- **滚动数组优化**：  
  ```python
  dp = [0] * (W + 1)  # 一维数组
  for i in range(n):
      for w in range(W, weight[i]-1, -1):  # 逆序遍历防覆盖
          dp[w] = max(dp[w], dp[w - weight[i]] + value[i])
  ```  
**为什么逆序？** 正序会导致同一物品被重复选取（退化为完全背包），逆序确保每次更新基于上一轮结果。  

**4. 实际场景应用**  
在**大模型训练资源调度**中：  
- 物品 = 不同任务（如文本生成/图像识别）  
- 重量 = 显存占用，价值 = 任务收益  
- 目标：在显存限制下最大化总收益。  
**代码关键点**：预处理物品列表，按价值密度排序可加速剪枝（非必须，但提升效率）。  

**5. 边界处理与复杂度**  
- **初始化**：`dp[0] = 0`（容量0时价值为0）  
- **时间复杂度**：`O(nW)`，空间优化后 `O(W)`  
- **陷阱提醒**：若物品重量为浮点数需离散化；超大 `W` 时考虑分支限界法。  

> **总结**：核心是状态设计的合理性 + 空间优化的工程意识。面试时可补充：“此思想也用于神经网络剪枝（如选择保留哪些通道）”，体现算法迁移能力。'),
  ('other-379', '

### 区间DP解题思路与实现要点

**1. 问题建模与状态定义**  
**为什么**：区间DP的核心是将问题分解为相邻子区间，通过合并子问题求解全局最优解。例如石子合并问题中，每次合并相邻两堆石子，最终合并为一堆的总代价最小。  
**怎么做**：定义`dp[i][j]`表示区间`[i,j]`的最优解（如最小代价/最大收益）。例如石子合并中，`dp[i][j]`表示合并第i到j堆石子的最小代价。  
```python
# 状态定义示例
dp = [[0] * n for _ in range(n)]  # n为区间长度
```

**2. 状态转移方程设计**  
**为什么**：需枚举区间分割点`k`，将`[i,j]`拆分为`[i,k]`和`[k+1,j]`，通过子区间结果推导当前区间解。  
**怎么做**：转移方程通常为`dp[i][j] = min/max(dp[i][k] + dp[k+1][j] + cost(i,j))`。例如石子合并中，`cost(i,j)`为区间`[i,j]`的总石子数（需预处理前缀和）。  
```python
# 转移方程示例（石子合并）
for length in range(2, n+1):  # 区间长度从2开始
    for i in range(n - length + 1):
        j = i + length - 1
        for k in range(i, j):
            dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + prefix[j+1] - prefix[i])
```

**3. 边界条件与初始化**  
**为什么**：长度为1的区间无需合并，代价为0，是递推基础。  
**怎么做**：初始化`dp[i][i] = 0`，并预处理前缀和数组`prefix`加速区间和计算。  
```python
# 初始化
for i in range(n): dp[i][i] = 0
prefix = [0] * (n+1)
for i in range(n): prefix[i+1] = prefix[i] + stones[i]
```

**4. 复杂度优化与场景适配**  
**为什么**：基础实现时间复杂度为O(n³)，需根据问题特性优化（如四边形不等式优化至O(n²)）。  
**怎么做**：若满足决策单调性（如`cost(i,j)`满足四边形不等式），可限制`k`的枚举范围。例如最优二叉搜索树问题中，`k`仅需在`[opt[i][j-1], opt[i+1][j]]`内枚举。  
```python
# 优化示例（四边形不等式）
for length in range(2, n+1):
    for i in range(n - length + 1):
        j = i + length - 1
        for k in range(opt[i][j-1], opt[i+1][j]+1):  # 缩小k范围
            ...
```

**5. 典型应用场景**  
**为什么**：区间DP适用于可分解为相邻子区间的问题，如矩阵链乘法、括号匹配、字符串编辑距离等。  
**怎么做**：以矩阵链乘法为例，`dp[i][j]`表示计算矩阵`A[i..j]`的最小乘法次数，转移方程为`dp[i][j] = min(dp[i][k] + dp[k+1][j] + p[i-1]*p[k]*p[j])`，其中`p`为矩阵维度数组。  

**总结**：区间DP的关键是合理定义状态、设计转移方程，并通过预处理和优化降低复杂度。实际编码时需注意循环顺序（先枚举区间长度，再枚举起点）和边界处理，避免越界或逻辑错误。'),
