### 反转链表参考答案  

#### 1. **核心思路：迭代法（推荐）**  
**为什么选迭代？**  
- 空间复杂度 O(1)，避免递归栈溢出风险，适合长链表场景。  
- 通过“三指针”动态调整节点指向，逻辑直观且高效。  

**怎么做？**  
- 初始化 `prev = null`（新链表头）、`curr = head`（当前节点）。  
- 循环中保存 `next = curr.next`，将 `curr.next` 指向 `prev`，再同步移动指针：  
  ```java
  while (curr != null) {
      Node next = curr.next; // 暂存下一节点
      curr.next = prev;      // 反转当前节点指向
      prev = curr;           // prev 前进
      curr = next;           // curr 前进
  }
  return prev; // 新头节点
  ```  
**场景示例**：  
原链表 `1->2->3->null` → 反转后 `3->2->1->null`。  

#### 2. **边界条件处理**  
**为什么重要？**  
- 空链表（`head = null`）或单节点链表直接返回，避免空指针异常。  

**怎么做？**  
- 在循环前校验 `if (head == null) return null;`，单节点时循环自然终止。  

#### 3. **复杂度分析**  
- **时间**：O(n)，遍历链表一次。  
- **空间**：O(1)，仅用常数级指针。  
**对比递归法**：递归需 O(n) 栈空间，可能栈溢出，但代码更简洁（面试中可简要提及）。  

#### 4. **易错点与优化**  
- **指针顺序**：必须先保存 `next` 再修改 `curr.next`，否则链表断裂。  
- **调试技巧**：用 ASCII 图跟踪指针变化：  
  ```
  初始: prev=null, curr=1->2->3->null  
  第1步: curr.next=prev → 1->null, prev=1, curr=2  
  第2步: curr.next=prev → 2->1->null, prev=2, curr=3  
  ```  

**总结**：迭代法是工业界首选，需熟练掌握指针操作逻辑，结合边界校验和复杂度分析，体现代码健壮性与性能意识。'),
